    let map = null, mapReady = false, leafletLoading = null;
    let mapMarkerGroup = null, standMarkerGroup = null, gaugeMarkerGroup = null, huntMarkerGroup = null, pinMarkerGroup = null;
    let adcnrOverlayGroup = null; // WMA / public lands polygons (ADCNR)
    let adcnrOpenPinGroup = null; // green pins on units open for selected weapon/date
