    /**
     * True when this unit uses its own AREA/permit calendar (not statewide deer-zone seasons).
     * Skyline, Black Warrior, NWRs with profiles, WMA Zone A/B slices, etc.
     */
    function usesUnitSpecificDeerRules(name, layerKey, attrs) {
      attrs = attrs || {};
      if (attrs.wmaZone) return true;
      if (typeof findUnitDeerProfile === 'function') {
        if (findUnitDeerProfile(name)) return true;
        if (attrs.Name && findUnitDeerProfile(attrs.Name)) return true;
      }
      if (typeof seasonsFromBuiltin === 'function') {
        try {
          var b = seasonsFromBuiltin(name);
          if (b && b.seasons && b.seasons.length) return true;
        } catch (eB) {}
      }
      if (layerKey === 'nwr') return true;
      return false;
    }
