    function buildHuntStatusBannerHtml(st) {
      if (!st) return '';
      var cls = 'unknown';
      var title = 'Verify before hunting';
      var wpnLabel = (selectedWeapon && selectedWeapon !== 'Either')
        ? displayWeaponName(selectedWeapon)
        : '';
      if (st.statusKnown && st.canHunt) {
        cls = 'open';
        title = huntCanTitle(selectedDate);
        if (wpnLabel) title = huntCanTitle(selectedDate) + ' with ' + wpnLabel;
      } else if (st.statusKnown && !st.canHunt) {
        cls = 'closed';
        if (wpnLabel) {
          title = "Can't hunt that day with " + wpnLabel;
        } else {
          title = huntCannotTitle(selectedDate);
        }
      }

      // "Can hunt with:" directly under the title (alt weapons or current open weapons)
      var canHuntWithLine = '';
      var canHuntWithList = [];
      if (st.statusKnown && st.canHunt) {
        if (st.openWeapons && st.openWeapons.length) {
          canHuntWithList = st.openWeapons.slice();
        } else if (wpnLabel) {
          canHuntWithList = [selectedWeapon];
        }
      } else if (st.statusKnown && !st.canHunt) {
        if (st.altWeapons && st.altWeapons.length) {
          canHuntWithList = st.altWeapons.slice();
        } else if (st.closedReason) {
          var cr0 = String(st.closedReason);
          var m0 = cr0.match(/Can hunt with:\s*([^.]+)/i) ||
            cr0.match(/Open with:\s*([^.]+)/i) ||
            cr0.match(/Open weapons[^:]*:\s*([^.]+)/i);
          if (m0) {
            canHuntWithLine = '<div class="mhs-line mhs-can-with" style="color:#86efac;font-weight:700;margin-top:2px;">Can hunt with: ' +
              escHtml(m0[1].trim()) + '</div>';
          }
        }
      }
      if (!canHuntWithLine && canHuntWithList.length) {
        canHuntWithLine =
          '<div class="mhs-line mhs-can-with" style="color:#86efac;font-weight:700;margin-top:2px;">Can hunt with: ' +
          escHtml(canHuntWithList.map(displayWeaponName).join(' Â· ')) + '</div>';
      }

      var unitSpecific = !!(st.unitSpecific ||
        (st.landKind === 'public' && usesUnitSpecificDeerRules(st.name, st.layerKey, { wmaZone: st.wmaZone, Name: st.name })));

      var lines = [];
      if (st.landKind === 'private') {
        lines.push('<div class="mhs-line">Private Property</div>');
        // Owner only (tax/parcel) â€” no address / parcel number clutter
        if (st.owner && String(st.owner).trim()) {
          lines.push('<div class="mhs-sub" style="margin-top:1px;">' + escHtml(String(st.owner).trim()) + '</div>');
        }
        lines.push('<div class="mhs-line">Deer Zone ' + escHtml(st.zone || 'A') + '</div>');
      } else {
        // Name already includes "(Zone B)" when on a multi-zone WMA
        lines.push('<div class="mhs-line">' + escHtml(st.name || 'Public land') + '</div>');
        // Skip statewide deer zone when this unit has its own AREA/permit calendar
        if (!unitSpecific) {
          lines.push('<div class="mhs-sub">Deer Zone ' + escHtml(st.zone || 'A') +
            (st.jurisdictionLabel ? ' Â· ' + escHtml(st.jurisdictionLabel) : '') + '</div>');
        } else if (st.jurisdictionLabel && !st.wmaZone) {
          lines.push('<div class="mhs-sub">' + escHtml(st.jurisdictionLabel) + '</div>');
        }
      }
      // Peak rut is deer-zone planning â€” omit when unit has its own rules (WMA/NWR profiles)
      if (!unitSpecific || st.landKind === 'private') {
        try {
          var rutInfo = formatPeakRutLineForZone(st.zone || 'A', selectedDate || new Date());
          lines.push(
            '<div class="mdm-rut-line' + (rutInfo.inPeak ? ' is-peak' : '') + '">' +
              (rutInfo.inPeak ? 'ðŸ¦Œ ' : '') +
              'Deer Zone ' + escHtml(rutInfo.zone) + ' peak rut: ' + escHtml(rutInfo.label) +
              (rutInfo.inPeak ? peakRutInWindowTag(selectedDate, 'caps') : '') +
            '</div>'
          );
        } catch (eRut) {}
      }
      // Distance from From-origin (GPS/ZIP/address) â€” yards until 1 mi, then miles
      try {
        if (typeof clickLat === 'number' && typeof clickLng === 'number' &&
            typeof distOriginLat === 'number' && typeof distOriginLng === 'number' &&
            typeof getDistanceMiles === 'function') {
          var miSt = getDistanceMiles(distOriginLat, distOriginLng, clickLat, clickLng);
          if (miSt != null && isFinite(miSt)) {
            var distSt = (typeof formatDistanceFromMe === 'function')
              ? formatDistanceFromMe(miSt)
              : (miSt.toFixed(1) + ' mi');
            lines.push('<div class="mhs-line" style="color:#7dd3fc;">' + distSt + ' from your From location</div>');
          }
        }
      } catch (eDistSt) {}
      if (selectedWeapon) {
        lines.push('<div class="mhs-sub">Weapon selected: ' + escHtml(displayWeaponName(selectedWeapon)) +
          ' Â· ' + escHtml(prettyDate(selectedDate || new Date())) + '</div>');
      }
      return (
        '<div class="mdm-hunt-status ' + cls + '">' +
          '<div class="mhs-title">' + escHtml(title) + '</div>' +
          canHuntWithLine +
          lines.join('') +
        '</div>'
      );
    }

