      // Stack: state mask (bottom) â†’ zone tint â†’ public lands â†’ markers
      try {
        if (stateZonesGroup) stateZonesGroup.bringToBack();
      } catch (ez) {}
      try { if (stateMaskGroup) stateMaskGroup.bringToBack(); } catch (eMask) {}
      try { adcnrOverlayGroup.bringToFront(); } catch (e) {}
      try { if (peakRutOverlayGroup) peakRutOverlayGroup.bringToFront(); } catch (eR) {}
