    function pinLatLngForEventSort() {
      var la = (typeof clickLat === 'number' && isFinite(clickLat)) ? clickLat : null;
      var lo = (typeof clickLng === 'number' && isFinite(clickLng)) ? clickLng : null;
      if (la == null && editingPinId) {
        try {
          var loc = locations.find(function (l) { return String(l.id) === String(editingPinId); });
          if (loc && isFinite(Number(loc.lat)) && isFinite(Number(loc.lng))) {
            la = Number(loc.lat); lo = Number(loc.lng);
          }
        } catch (e) {}
      }
      return { lat: la, lng: lo };
    }
    function formatEventDistLabel(mi) {
      if (mi == null || !isFinite(mi)) return 'No location on event';
      if (mi < 0.1) return Math.round(mi * 5280) + ' ft away';
      if (mi < 10) return mi.toFixed(1) + ' mi away';
      return Math.round(mi) + ' mi away';
    }
    function listEventsForPinLink() {
      var pin = pinLatLngForEventSort();
      var list = [];
      try {
        if (window.RegSlayerCalendarEvents && typeof window.RegSlayerCalendarEvents.all === 'function') {
          list = window.RegSlayerCalendarEvents.all().slice();
        }
      } catch (e) {}
      list.forEach(function (ev) {
        var d = null;
        if (pin.lat != null && pin.lng != null && ev.lat != null && ev.lng != null &&
            isFinite(Number(ev.lat)) && isFinite(Number(ev.lng)) &&
            typeof haversineMiles === 'function') {
          d = haversineMiles(pin.lat, pin.lng, Number(ev.lat), Number(ev.lng));
        }
        ev._distMi = d;
      });
      // Closest first; events without location last, then by start date
      list.sort(function (a, b) {
        var da = a._distMi, db = b._distMi;
        var aHas = da != null && isFinite(da);
        var bHas = db != null && isFinite(db);
        if (aHas && bHas && da !== db) return da - db;
        if (aHas && !bHas) return -1;
        if (!aHas && bHas) return 1;
        return String(a.startDate || '').localeCompare(String(b.startDate || ''));
      });
      return list;
    }
