      if (!sheet || !head || head._wiredPesDrag) return;
      head._wiredPesDrag = true;
      var dragging = false, sx = 0, sy = 0, origBottom = 0, origLeft = 0;
      head.addEventListener('mousedown', function(ev) {
        if (ev.target && ev.target.closest && ev.target.closest('.pes-close')) return;
        dragging = true;
        sx = ev.clientX; sy = ev.clientY;
        var r = sheet.getBoundingClientRect();
        origBottom = window.innerHeight - r.bottom;
        origLeft = r.left;
        sheet.style.right = 'auto';
        sheet.style.width = r.width + 'px';
        ev.preventDefault();
      });
      window.addEventListener('mousemove', function(ev) {
        if (!dragging) return;
        var dx = ev.clientX - sx;
        var dy = ev.clientY - sy;
        sheet.style.position = 'fixed';
        sheet.style.left = Math.max(4, origLeft + dx) + 'px';
        sheet.style.bottom = Math.max(4, origBottom - dy) + 'px';
        sheet.style.transform = 'none';
      });
      window.addEventListener('mouseup', function() { dragging = false; });
