      mapMarkerGroup = L.layerGroup().addTo(map);
      standMarkerGroup = L.layerGroup().addTo(map);
      gaugeMarkerGroup = L.layerGroup().addTo(map);
      huntMarkerGroup = L.layerGroup().addTo(map);
