      var fromGps = !!(opts.fromGps || mapDotMenuSource === 'gps');
      var pl = lastClickPublicLand;
      var st = null;
      try {
        if (clickLat != null && clickLng != null) st = evaluateMapSpotHuntStatus(clickLat, clickLng);
      } catch (eSt) { st = null; }
