            '<button type="button" class="mdm-btn" style="background:#1a4a5c;" onclick="event.preventDefault();event.stopPropagation();window.handleMapDotAction(\'offline-mi5\');return false;">5 miles</button>' +
            '<button type="button" class="mdm-btn" style="background:#1a4a5c;" onclick="event.preventDefault();event.stopPropagation();window.handleMapDotAction(\'offline-mi10\');return false;">10 miles</button>' +
            '<button type="button" class="mdm-btn" style="background:#3a4234;" onclick="event.preventDefault();event.stopPropagation();window.handleMapDotAction(\'offline-back\');return false;">Back</button>' +
            '</div>' +
          '</div>'
