      // Freeze map on-screen before any weather/list DOM work (mobile)
      if (!skipWeather && typeof lockMapInView === 'function') lockMapInView();
      clickLat = latlng.lat;
      clickLng = latlng.lng;
      lastClickTva = null;
      lastClickParcel = null;
