    /**
     * Download basemap tiles. Always shows confirm with estimated size.
     * opts.tierId: mi2 | mi5 | mi10 | overview
     */
    function saveOfflineMapAround(lat, lng, opts) {
      opts = opts || {};
      var tierId = opts.tierId || 'mi2';
      var tier = (window.RegSlayerOffline && RegSlayerOffline.getTier)
        ? RegSlayerOffline.getTier(tierId)
        : { id: tierId, name: tierId, radiusMi: 2, mode: 'circle', zMin: 10, zMax: 15 };
      var isOverview = tier.mode === 'alabama_bbox';
      if (!isOverview && (lat == null || lng == null || isNaN(lat) || isNaN(lng))) {
        if (typeof showAppCopyToast === 'function') {
          showAppCopyToast('<span class="act">Offline map</span><br>No location to save offline.');
        }
        return Promise.resolve(null);
      }
      if (!window.RegSlayerOffline || typeof RegSlayerOffline.saveOfflineAround !== 'function') {
        if (typeof showAppCopyToast === 'function') {
          showAppCopyToast('<span class="act">Offline map</span><br>Offline engine not loaded.');
        }
        return Promise.resolve(null);
      }
      if (!navigator.onLine) {
        if (typeof showAppCopyToast === 'function') {
          showAppCopyToast('<span class="act">Offline map</span><br>Need network once to download tiles.');
        }
        return Promise.resolve(null);
      }
      var basemap = opts.basemap || getOfflineBasemapFromUi();
      if (isOverview && (basemap === 'satellite' || basemap === 'lidar')) basemap = 'topo';
      var est = RegSlayerOffline.estimatePack(lat || 32.6, lng || -86.8, basemap, tierId);
      var label = opts.label || (isOverview ? 'Alabama overview' : 'Map spot');
      var coverLine = isOverview
        ? 'Coverage: <strong>Statewide Alabama</strong> (zoom ' + est.zMin + 'â€“' + est.zMax + ')'
        : ('Radius: <strong>' + escHtml(String(est.radiusMi || tier.radiusMi || 2)) + ' miles</strong> Â· zoom ' +
          est.zMin + 'â€“' + est.zMax);
      var detail =
        '<strong style="color:var(--accent);">Confirm offline download</strong><br><br>' +
        'Pack: <strong>' + escHtml(tier.name || tierId) + '</strong><br>' +
        'Around: <strong>' + escHtml(label) + '</strong><br>' +
        coverLine + '<br>' +
        'Basemap: <strong>' + escHtml(basemap) + '</strong><br>' +
        'Estimated size: <strong>~' + escHtml(String(est.approxMb)) + ' MB</strong> ' +
        '(' + escHtml(String(est.tileCount)) + ' tiles)<br>' +
        '<span style="color:var(--muted);font-size:11px;">' + escHtml(tier.sizeHint || '') + '</span><br><br>' +
        'Needs good signal while downloading. Use Wiâ€‘Fi for 10 miles or statewide. Online use is unchanged.';

      return showOfflineMapConfirm(detail).then(function(ok) {
        if (!ok) return null;

        if (typeof showAppCopyToast === 'function') {
          showAppCopyToast('<span class="act">Downloading offline mapâ€¦</span><br>' +
            escHtml(tier.name || '') + ' Â· ~' + escHtml(String(est.approxMb)) + ' MB Â· ' + escHtml(label));
        }
        if (map) try { map.closePopup(); } catch (eC) {}

        return RegSlayerOffline.saveOfflineAround(lat, lng, {
          label: label,
          basemap: basemap,
          tierId: tierId,
          source: opts.source || 'pin',
          sourceId: opts.sourceId || null,
          onProgress: function(p) {
            if (window.RegSlayerOffline) {
              RegSlayerOffline.updateOfflineBanner(
                'Offline map ' + (p.pct || 0) + '% (' + p.ok + '/' + p.total + ' tiles)'
              );
            }
          }
        }).then(function(pack) {
          var msg = pack && pack.status === 'ready'
            ? ('Offline map ready Â· ' + (pack.ok || 0) + ' tiles Â· ' + (pack.tierName || tier.name) + ' Â· ' + label)
            : ('Offline map finished with issues Â· ok ' + (pack && pack.ok) + ' / fail ' + (pack && pack.fail));
          if (typeof showAppCopyToast === 'function') {
            showAppCopyToast('<span class="act">Offline map</span><br>' + escHtml(msg));
          }
          if (window.RegSlayerOffline) {
            RegSlayerOffline.updateOfflineBanner(pack && pack.status === 'ready' ? 'Offline map saved' : null);
          }
          try { if (window.refreshOfflinePacksSummary) window.refreshOfflinePacksSummary(); } catch (eR) {}
          return pack;
        }).catch(function(err) {
          if (typeof showAppCopyToast === 'function') {
            showAppCopyToast('<span class="act">Offline map failed</span><br>' +
              escHtml((err && err.message) || 'Download failed.'));
          }
          return null;
        });
      });
    }
    window.saveOfflineMapAround = saveOfflineMapAround;

    /** Settings: statewide Alabama topo pack */
    window.downloadStatewideOfflineOverview = function() {
      return saveOfflineMapAround(32.6, -86.8, {
        label: 'Alabama overview',
        source: 'settings-overview',
        basemap: 'topo',
        tierId: 'overview'
      });
    };

    window.saveOfflineMapForCustomArea = function(areaId) {
      var areas = typeof loadCustomAreasFromStorage === 'function' ? loadCustomAreasFromStorage() : [];
      var area = null;
      for (var i = 0; i < areas.length; i++) {
        if (String(areas[i].id) === String(areaId)) { area = areas[i]; break; }
      }
      if (!area) {
        var loc = locations && locations.find(function(l) { return l && String(l.id) === String(areaId); });
        area = loc;
      }
      if (!area) {
        alert('Custom area not found.');
        return;
      }
      var c = (area.ring && typeof ringCentroid === 'function')
        ? (ringCentroid(area.ring) || { lat: area.lat, lng: area.lng })
        : { lat: area.lat, lng: area.lng };
      if (!c || c.lat == null) {
        alert('Could not find center of custom area.');
        return;
      }
      saveOfflineMapAround(c.lat, c.lng, {
        label: area.name || 'Custom area',
        source: 'custom-area',
        sourceId: area.id
      });
    };

    // ========== MEASURE / DRAW CUSTOM HUNT AREAS ==========
    function haversineMiles(lat1, lng1, lat2, lng2) {
      var R = 3958.7613;
      var toRad = Math.PI / 180;
      var dLat = (lat2 - lat1) * toRad;
      var dLng = (lng2 - lng1) * toRad;
      var a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(lat1 * toRad) * Math.cos(lat2 * toRad) *
        Math.sin(dLng / 2) * Math.sin(dLng / 2);
      return 2 * R * Math.asin(Math.min(1, Math.sqrt(a)));
    }

    function pathDistanceMiles(points) {
      var total = 0;
      for (var i = 1; i < points.length; i++) {
        total += haversineMiles(points[i - 1].lat, points[i - 1].lng, points[i].lat, points[i].lng);
      }
      return total;
    }

    function formatMiles(mi) {
      if (mi == null || isNaN(mi)) return 'â€”';
      if (mi < 0.1) return (mi * 5280).toFixed(0) + ' ft';
      if (mi < 10) return mi.toFixed(2) + ' mi';
      return mi.toFixed(1) + ' mi';
    }
    // formatDistanceFromMe is defined next to getDistanceMiles (yards until 1 mi)

    function ringCentroid(ring) {
      if (!ring || !ring.length) return null;
      var slat = 0, slng = 0, n = 0;
      for (var i = 0; i < ring.length; i++) {
        if (ring[i] && ring[i].length >= 2) {
          slat += ring[i][0];
          slng += ring[i][1];
          n++;
        }
      }
      if (!n) return null;
      return { lat: slat / n, lng: slng / n };
    }

    /**
     * While Measure / Draw is active, kill clicks on WMAs, zones, pins, etc.
     * so only the tool receives map clicks (no popups / tooltips from overlays).
     * Works with Leaflet Canvas + SVG (preferCanvas maps).
     */
    function setLayerClickable(layer, clickable) {
      if (!layer) return;
      try {
        if (layer.options) layer.options.interactive = !!clickable;
        // SVG / DivIcon DOM
        if (layer.getElement) {
          var el = layer.getElement();
          if (el && el.style) el.style.pointerEvents = clickable ? '' : 'none';
        }
        if (layer._path && layer._path.style) {
          layer._path.style.pointerEvents = clickable ? '' : 'none';
        }
        if (layer._icon && layer._icon.style) {
          layer._icon.style.pointerEvents = clickable ? '' : 'none';
        }
        if (layer._shadow && layer._shadow.style) {
          layer._shadow.style.pointerEvents = clickable ? '' : 'none';
        }
        // Nested marker icon content
        if (layer._icon && layer._icon.querySelectorAll) {
          var kids = layer._icon.querySelectorAll('*');
          for (var i = 0; i < kids.length; i++) {
            if (kids[i].style) kids[i].style.pointerEvents = clickable ? '' : 'none';
          }
        }
        if (!clickable) {
          try {
            if (layer.closePopup) layer.closePopup();
            if (layer.closeTooltip) layer.closeTooltip();
            if (layer.unbindTooltip && layer.getTooltip && layer.getTooltip()) {
              // Keep tooltip bound; interactive=false prevents open. Do not unbind permanently.
            }
          } catch (e0) {}
        }
      } catch (e) {}
    }

    function applyMapDrawInteractionLock() {
      var lock = !!(mapDrawMode === 'measure' || mapDrawMode === 'draw' || mapDrawMode === 'drawline');
      if (map) {
        try {
          map.closePopup();
          if (map.closeTooltip) map.closeTooltip();
        } catch (e1) {}
      }
      // All clickable map overlays / markers that should not steal tool clicks
      var groups = [
        adcnrOverlayGroup,
        adcnrOpenPinGroup,
        stateZonesGroup,
        customAreaGroup,
        measuredPathGroup,
        pinMarkerGroup,
        huntMarkerGroup,
        mapMarkerGroup,
        standMarkerGroup,
        gaugeMarkerGroup
      ];
      // Leave mapDrawPreviewLayer / vertex dots fully interactive â€” they close the shape
      groups.forEach(function(g) {
        if (!g || typeof g.eachLayer !== 'function') return;
        g.eachLayer(function(layer) {
          setLayerClickable(layer, !lock);
        });
      });
      // Lone markers not in groups (would otherwise steal draw clicks)
      if (typeof gpsMarker !== 'undefined' && gpsMarker) setLayerClickable(gpsMarker, !lock);
      if (typeof tempClickMarker !== 'undefined' && tempClickMarker) setLayerClickable(tempClickMarker, !lock);
      if (typeof distOriginMarker !== 'undefined' && distOriginMarker) setLayerClickable(distOriginMarker, !lock);
      // Hard block: while locked, ignore popupopen from any leftover handlers
      if (map) {
        if (lock && !map._drawPopupBlocker) {
          map._drawPopupBlocker = function(e) {
            if (mapDrawMode === 'measure' || mapDrawMode === 'draw' || mapDrawMode === 'drawline') {
              try {
                if (e && e.popup && e.popup._source && e.popup._source.closePopup) {
                  e.popup._source.closePopup();
                }
                map.closePopup();
              } catch (e2) {}
            }
          };
          map.on('popupopen', map._drawPopupBlocker);
          map._drawTooltipBlocker = function() {
            if (mapDrawMode === 'measure' || mapDrawMode === 'draw' || mapDrawMode === 'drawline') {
              try { if (map.closeTooltip) map.closeTooltip(); } catch (e3) {}
            }
          };
          map.on('tooltipopen', map._drawTooltipBlocker);
        } else if (!lock && map._drawPopupBlocker) {
          map.off('popupopen', map._drawPopupBlocker);
          map._drawPopupBlocker = null;
          if (map._drawTooltipBlocker) {
            map.off('tooltipopen', map._drawTooltipBlocker);
            map._drawTooltipBlocker = null;
          }
        }
      }
    }

    function setMapDrawUi() {
      var measuring = mapDrawMode === 'measure';
      var drawing = mapDrawMode === 'draw';
      var drawingLine = mapDrawMode === 'drawline';
      var active = !!(measuring || drawing || drawingLine);
      var wrap = document.querySelector('.map-wrapper');
      if (wrap) {
        wrap.classList.toggle('draw-mode', active);
        wrap.classList.toggle('mode-measure', measuring);
        wrap.classList.toggle('mode-draw', drawing || drawingLine);
        wrap.classList.toggle('mode-drawline', drawingLine);
        wrap.classList.toggle('tool-chrome-active', active);
      }
      // Measure icon / draw icon cursor on the map
      try {
        if (typeof applyActiveToolCursor === 'function') applyActiveToolCursor();
        else {
          var mapEl0 = document.getElementById('leaflet-map');
          if (mapEl0) mapEl0.style.cursor = active ? 'crosshair' : '';
        }
        if (!active) {
          var mapEl1 = document.getElementById('leaflet-map');
          var lc1 = document.querySelector('.map-wrapper .leaflet-container');
          if (mapEl1) mapEl1.style.cursor = '';
          if (lc1) lc1.style.cursor = '';
          if (typeof map !== 'undefined' && map && map.getContainer) map.getContainer().style.cursor = '';
        }
      } catch (eCur) {}
      var tools = document.getElementById('map-draw-tools');
      if (tools) {
        tools.classList.toggle('tool-active', active);
        tools.classList.toggle('mode-measure', measuring);
        tools.classList.toggle('mode-draw', drawing || drawingLine);
      }
      // Keep Tools drawer open while a tool is active so Finish / Cancel stay reachable (panel docks top-left)
      if (active && typeof setMapToolsMenuOpen === 'function') setMapToolsMenuOpen(true);
      applyMapDrawInteractionLock();
      var bMeas = document.getElementById('mdt-measure');
      var bDraw = document.getElementById('mdt-draw');
      var bUndo = document.getElementById('mdt-undo');
      var bFin = document.getElementById('mdt-finish');
      var bCan = document.getElementById('mdt-cancel');
      var hint = document.getElementById('map-draw-hint');
      var stats = document.getElementById('map-draw-stats');
      if (bMeas) {
        bMeas.classList.toggle('active', measuring);
        bMeas.title = measuring
          ? 'Measuring â€” click again or Cancel to exit'
          : 'Click points to measure distance';
      }
      if (bDraw) {
        bDraw.classList.toggle('active', drawing || drawingLine);
        bDraw.title = (drawing || drawingLine)
          ? 'Drawing â€” click again or Cancel to exit'
          : 'Draw line or shape';
      }
      var hasDraft = mapDrawPoints.length > 0 || !!(mapDrawPreviewLayer && mapDrawPreviewLayer.getLayers && mapDrawPreviewLayer.getLayers().length);
      if (bUndo) bUndo.disabled = !active || mapDrawPoints.length === 0;
      if (bFin) bFin.disabled = !active || mapDrawPoints.length < (drawing ? 3 : 2);
      // Allow Cancel whenever a draft path is on screen (including finished measure preview)
      if (bCan) bCan.disabled = !active && !hasDraft;
      if (hint) {
        if (measuring) {
          hint.classList.add('active');
          hint.innerHTML = '<strong>Measure</strong> â€” tap map points. Double-click or <strong>Finish</strong> when done.';
        } else if (drawing) {
          hint.classList.add('active');
          hint.innerHTML = '<strong>Draw shape</strong> â€” 3+ corners. Tap an existing <strong>dot</strong> (or Finish) to close.';
        } else if (drawingLine) {
          hint.classList.add('active');
          hint.innerHTML = '<strong>Draw line</strong> â€” tap map points. Double-click, tap a point again, or <strong>Finish</strong> to save.';
        } else {
          hint.classList.remove('active');
          hint.innerHTML = '';
        }
      }
      if (stats) {
        if (active && mapDrawPoints.length) {
          var pts = mapDrawPoints.slice();
          if (mapDrawMouseLatLng && pts.length) {
            pts = pts.concat([{ lat: mapDrawMouseLatLng.lat, lng: mapDrawMouseLatLng.lng }]);
          }
          var dist = pathDistanceMiles(pts);
          var line = formatMiles(dist);
          if (drawing && mapDrawPoints.length >= 3) {
            stats.innerHTML = mapDrawPoints.length + ' pts Â· ~' + line;
          } else {
            stats.innerHTML = mapDrawPoints.length + ' pt' + (mapDrawPoints.length === 1 ? '' : 's') + ' Â· ' + line;
          }
          stats.classList.add('active');
        } else if (active) {
          stats.innerHTML = 'Tap map for first point';
          stats.classList.add('active');
        } else {
          stats.classList.remove('active');
          stats.innerHTML = '';
        }
      }
    }

    function clearMapDrawPreview() {
      mapDrawLineLayer = null;
      mapDrawLineHaloLayer = null;
      mapDrawFillLayer = null;
      mapDrawVertexGroup = null;
      if (mapDrawPreviewLayer) mapDrawPreviewLayer.clearLayers();
    }

    /** Stats/hint only â€” safe to call from mousemove (no layer rebuild). */
    function updateMapDrawStatsOnly() {
      var stats = document.getElementById('map-draw-stats');
      if (!stats || !mapDrawMode) return;
      if (!mapDrawPoints.length) {
        stats.innerHTML = 'Tap map for first point';
        stats.classList.add('active');
        return;
      }
      var pts = mapDrawPoints.slice();
      if (mapDrawMouseLatLng && pts.length) {
        pts = pts.concat([{ lat: mapDrawMouseLatLng.lat, lng: mapDrawMouseLatLng.lng }]);
      }
      var dist = pathDistanceMiles(pts);
      var line = formatMiles(dist);
      var drawing = mapDrawMode === 'draw';
      if (drawing && mapDrawPoints.length >= 3) {
        stats.innerHTML = mapDrawPoints.length + ' pts Â· ~' + line;
      } else {
        stats.innerHTML = mapDrawPoints.length + ' pt' + (mapDrawPoints.length === 1 ? '' : 's') + ' Â· ' + line;
      }
      stats.classList.add('active');
    }

    /** Update only the draft line to the cursor â€” keeps vertex markers stable for click-to-close. */
    function updateMapDrawRubberBand() {
      if (!map || !mapDrawPreviewLayer || !mapDrawMode || !mapDrawPoints.length) return;
      /* Measure + draw-line share the same dashed creation UX */
      var isPathDraft = mapDrawMode === 'measure' || mapDrawMode === 'drawline';
      var isMeasure = mapDrawMode === 'measure';
      var color = isMeasure ? MEASURE_LINE_COLOR : '#e59a18';
      var haloColor = isMeasure ? MEASURE_LINE_HALO : 'rgba(255, 248, 220, 0.95)';
      var latlngs = mapDrawPoints.map(function(p) { return [p.lat, p.lng]; });
      if (mapDrawMouseLatLng) {
        latlngs = latlngs.concat([[mapDrawMouseLatLng.lat, mapDrawMouseLatLng.lng]]);
      }
      // Light halo under dashed path (measure + draw-line) so dashes read on any basemap
      if (isPathDraft) {
        if (mapDrawLineHaloLayer && mapDrawPreviewLayer.hasLayer(mapDrawLineHaloLayer)) {
          try {
            mapDrawLineHaloLayer.setLatLngs(latlngs);
            mapDrawLineHaloLayer.setStyle({
              color: haloColor,
              weight: 7,
              opacity: 0.95,
              dashArray: '7 7',
              lineCap: 'round',
              lineJoin: 'round'
            });
          } catch (eHalo) {
            mapDrawLineHaloLayer = null;
          }
        }
        if (!mapDrawLineHaloLayer) {
          mapDrawLineHaloLayer = L.polyline(latlngs, {
            color: haloColor,
            weight: 7,
            opacity: 0.95,
            dashArray: '7 7',
            lineCap: 'round',
            lineJoin: 'round',
            interactive: false
          }).addTo(mapDrawPreviewLayer);
        }
      } else if (mapDrawLineHaloLayer) {
        try { mapDrawPreviewLayer.removeLayer(mapDrawLineHaloLayer); } catch (eRmH) {}
        mapDrawLineHaloLayer = null;
      }
      if (mapDrawLineLayer && mapDrawPreviewLayer.hasLayer(mapDrawLineLayer)) {
        try {
          mapDrawLineLayer.setLatLngs(latlngs);
          mapDrawLineLayer.setStyle({
            color: color,
            weight: isPathDraft ? 3.5 : 3,
            opacity: 1,
            dashArray: isPathDraft ? '7 7' : null,
            lineCap: 'round',
            lineJoin: 'round'
          });
        } catch (eLine) {
          mapDrawLineLayer = null;
        }
      }
      if (!mapDrawLineLayer) {
        mapDrawLineLayer = L.polyline(latlngs, {
          color: color,
          weight: isPathDraft ? 3.5 : 3,
          opacity: 1,
          dashArray: isPathDraft ? '7 7' : null,
          lineCap: 'round',
          lineJoin: 'round',
          interactive: false
        }).addTo(mapDrawPreviewLayer);
      }
    }

    function closeShapeFromVertexClick(ev) {
      try {
        if (ev) {
          if (ev.originalEvent) {
            L.DomEvent.stopPropagation(ev.originalEvent);
            L.DomEvent.preventDefault(ev.originalEvent);
          }
          L.DomEvent.stop(ev);
        }
      } catch (eStop) {}
      if (mapDrawMode === 'draw' && mapDrawPoints.length >= 3) {
        mapDrawLastClickAt = 0;
        mapDrawLastClickLatLng = null;
        finishMapDraw();
      }
    }

    function refreshMapDrawPreview() {
      if (!map || !mapDrawPreviewLayer) return;
      clearMapDrawPreview();
      if (!mapDrawPoints.length) {
        setMapDrawUi();
        return;
      }
      var color = mapDrawMode === 'measure' ? MEASURE_LINE_COLOR : '#e59a18';
      // Soft fill preview for shape (3+ corners)
      if (mapDrawMode === 'draw' && mapDrawPoints.length >= 3) {
        var fillPts = mapDrawPoints.map(function(p) { return [p.lat, p.lng]; });
        mapDrawFillLayer = L.polygon(fillPts, {
          color: color,
          weight: 1,
          fillColor: color,
          fillOpacity: 0.12,
          interactive: false
        }).addTo(mapDrawPreviewLayer);
      }
      // Rubber-band line (includes cursor guide)
      updateMapDrawRubberBand();

      // Vertices as DOM DivIcon markers (marker pane) so preferCanvas cannot eat clicks.
      // Shape: previous dots close polygon.
      // Measure + draw-line: same creation UX â€” any existing vertex ends the path.
      mapDrawVertexGroup = L.layerGroup().addTo(mapDrawPreviewLayer);
      mapDrawPoints.forEach(function(p, idx) {
        var isDraw = mapDrawMode === 'draw';
        var isLine = mapDrawMode === 'drawline';
        var isMeasurePt = mapDrawMode === 'measure';
        var isPathDraft = isMeasurePt || isLine;
        var canClose = isDraw && mapDrawPoints.length >= 3 && idx < mapDrawPoints.length - 1;
        var isLatest = idx === mapDrawPoints.length - 1;
        // Path modes (measure + line): re-tap any vertex (incl. latest) to finish â€” same as measure
        var pathCanFinish = isPathDraft && mapDrawPoints.length >= 2;
        var cls = 'draw-vertex-dot';
        if (canClose) cls += ' is-close' + (idx === 0 ? ' is-first' : '');
        else if (isPathDraft) cls += ' is-measure';
        else if (isLatest) cls += ' is-latest';
        else cls += ' is-latest';

        var size = canClose ? (idx === 0 ? 24 : 22) : (isPathDraft ? 20 : 18);
        /* No hover â€œtap again to finishâ€ tips on measure/line â€” feels clunky */
        var m = L.marker([p.lat, p.lng], {
          icon: L.divIcon({
            className: 'draw-vertex-icon',
            html: '<div class="' + cls + '"></div>',
            iconSize: [size, size],
            iconAnchor: [size / 2, size / 2]
          }),
          interactive: !!(canClose || pathCanFinish),
          keyboard: false,
          zIndexOffset: canClose ? 2500 : (pathCanFinish ? 2400 : 2000),
          bubblingMouseEvents: false
        });
        function stopAndFinish(ev) {
          try {
            if (ev) L.DomEvent.stop(ev);
            if (ev && ev.originalEvent) {
              L.DomEvent.stopPropagation(ev.originalEvent);
              L.DomEvent.preventDefault(ev.originalEvent);
            }
          } catch (eS) {}
          mapDrawLastClickAt = 0;
          mapDrawLastClickLatLng = null;
          finishMapDraw();
        }
        if (canClose) {
          m.on('mousedown', function(ev) {
            try {
              if (ev && ev.originalEvent) {
                L.DomEvent.stopPropagation(ev.originalEvent);
                L.DomEvent.preventDefault(ev.originalEvent);
              }
            } catch (eMd) {}
          });
          m.on('click', closeShapeFromVertexClick);
        } else if (pathCanFinish) {
          m.on('mousedown', function(ev) {
            try {
              if (ev && ev.originalEvent) {
                L.DomEvent.stopPropagation(ev.originalEvent);
                L.DomEvent.preventDefault(ev.originalEvent);
              }
            } catch (eMm) {}
          });
          m.on('click', stopAndFinish);
        }
        m.addTo(mapDrawVertexGroup);
      });

      // Segment distance labels (measure + draw-line â€” same creation feedback)
      if ((mapDrawMode === 'measure' || mapDrawMode === 'drawline') && mapDrawPoints.length >= 2) {
        for (var i = 1; i < mapDrawPoints.length; i++) {
          var a = mapDrawPoints[i - 1], b = mapDrawPoints[i];
          var mid = { lat: (a.lat + b.lat) / 2, lng: (a.lng + b.lng) / 2 };
          var seg = haversineMiles(a.lat, a.lng, b.lat, b.lng);
          L.marker([mid.lat, mid.lng], {
            interactive: false,
            keyboard: false,
            icon: L.divIcon({
              className: '',
              html: '<div style="background:rgba(12,25,41,0.94);border:1px solid #eef2f7;color:#fff;font-size:10px;font-weight:700;padding:2px 5px;border-radius:4px;white-space:nowrap;pointer-events:none;box-shadow:0 1px 4px rgba(0,0,0,0.45);">' + formatMiles(seg) + '</div>',
              iconSize: [70, 18],
              iconAnchor: [35, 9]
            })
          }).addTo(mapDrawPreviewLayer);
        }
      }
      // Keep draft above overlays so close-dots receive the click
      try {
        if (mapDrawPreviewLayer.bringToFront) mapDrawPreviewLayer.bringToFront();
      } catch (eBf) {}
      setMapDrawUi();
    }

    function addMapDrawVertex(latlng) {
      if (!mapDrawMode || !latlng) return;
      mapDrawPoints.push({ lat: latlng.lat, lng: latlng.lng });
      mapDrawMouseLatLng = null; // reset guide so next segment starts clean
      refreshMapDrawPreview();
    }

    /** Double-click zoom stays off globally (popups / dots). Draw tools use dblclick only to Finish. */
    function setMapDrawDoubleClickZoom(/* enabled */) {
      if (!map || !map.doubleClickZoom) return;
      try {
        map.doubleClickZoom.disable();
      } catch (e) {}
    }

    /** Pixel-radius hit test for existing draw vertices (zoom-independent). */
    function findNearbyDrawVertexIndex(latlng, maxPx) {
      if (!map || !latlng || !mapDrawPoints.length) return -1;
      maxPx = maxPx == null ? 36 : maxPx;
      var clickPt;
      try {
        clickPt = map.latLngToContainerPoint(L.latLng(latlng.lat, latlng.lng));
      } catch (ePt) {
        return -1;
      }
      var best = -1;
      var bestD = maxPx * maxPx;
      for (var i = 0; i < mapDrawPoints.length; i++) {
        var p = mapDrawPoints[i];
        if (!p) continue;
        var vp;
        try {
          vp = map.latLngToContainerPoint(L.latLng(p.lat, p.lng));
        } catch (eVp) {
          continue;
        }
        var dx = clickPt.x - vp.x;
        var dy = clickPt.y - vp.y;
        var d = dx * dx + dy * dy;
        if (d <= bestD) {
          bestD = d;
          best = i;
        }
      }
      return best;
    }

    /**
     * Single click = add vertex.
     * Measure: double-click OR click the same/existing point again â†’ finish.
     * Draw: click near a previous vertex closes the shape; double-click also finishes.
     */
    function handleMapDrawToolClick(latlng, e) {
      if (!mapDrawMode || !latlng) return;
      var now = Date.now();
      var isDouble = false;
      if (mapDrawLastClickAt && (now - mapDrawLastClickAt) < 450 && mapDrawLastClickLatLng) {
        var dMi = haversineMiles(
          mapDrawLastClickLatLng.lat, mapDrawLastClickLatLng.lng,
          latlng.lat, latlng.lng
        );
        // Same-ish spot within ~80 ft counts as double-click finish
        if (dMi < 0.015) isDouble = true;
      }

      // Measure + draw-line: re-click any existing vertex â†’ finish (identical creation UX)
      if (!isDouble && (mapDrawMode === 'measure' || mapDrawMode === 'drawline') && mapDrawPoints.length >= 2) {
        var nearMeas = findNearbyDrawVertexIndex(latlng, 36);
        if (nearMeas >= 0) {
          mapDrawLastClickAt = 0;
          mapDrawLastClickLatLng = null;
          if (e && e.originalEvent) {
            try {
              L.DomEvent.stopPropagation(e.originalEvent);
              L.DomEvent.preventDefault(e.originalEvent);
            } catch (errMeas) {}
          }
          finishMapDraw();
          return;
        }
      }

      // Draw: click near a previous corner (not the latest) â†’ complete the shape
      // Pixel hit-test is the reliable path when marker click is swallowed by Canvas/overlays
      if (!isDouble && mapDrawMode === 'draw' && mapDrawPoints.length >= 3) {
        var nearIdx = findNearbyDrawVertexIndex(latlng, 40);
        if (nearIdx >= 0 && nearIdx < mapDrawPoints.length - 1) {
          mapDrawLastClickAt = 0;
          mapDrawLastClickLatLng = null;
          if (e && e.originalEvent) {
            try {
              L.DomEvent.stopPropagation(e.originalEvent);
              L.DomEvent.preventDefault(e.originalEvent);
            } catch (errClose) {}
          }
          finishMapDraw();
          return;
        }
      }

      mapDrawLastClickAt = now;
      mapDrawLastClickLatLng = { lat: latlng.lat, lng: latlng.lng };

      if (isDouble) {
        if (e && e.originalEvent) {
          try {
            L.DomEvent.stopPropagation(e.originalEvent);
            L.DomEvent.preventDefault(e.originalEvent);
          } catch (err) {}
        }
        endMapDrawFromDoubleClick();
        return;
      }
      addMapDrawVertex(latlng);
    }

    /** Double-click finish: drop accidental last vertex from the 2nd click, then finish. */
    function endMapDrawFromDoubleClick() {
      if (!mapDrawMode) return;
      // The second click of a double-click usually already added a near-duplicate point
      if (mapDrawPoints.length >= 2) {
        var a = mapDrawPoints[mapDrawPoints.length - 1];
        var b = mapDrawPoints[mapDrawPoints.length - 2];
        if (a && b && haversineMiles(a.lat, a.lng, b.lat, b.lng) < 0.02) {
          mapDrawPoints.pop();
          refreshMapDrawPreview();
        }
      }
      mapDrawLastClickAt = 0;
      mapDrawLastClickLatLng = null;
      finishMapDraw();
    }
    window.endMapDrawFromDoubleClick = endMapDrawFromDoubleClick;

    function undoMapDrawVertex() {
      if (!mapDrawPoints.length) return;
      mapDrawPoints.pop();
      refreshMapDrawPreview();
    }

    /** Show/hide full-screen prompt modals (shape save, path edit). Hidden on load until prompted. */
    function showAppPromptModal(id) {
      var modal = document.getElementById(id);
      if (!modal) return;
      modal.hidden = false;
      modal.classList.add('active');
      modal.style.display = 'flex';
    }
    function hideAppPromptModal(id) {
      var modal = document.getElementById(id);
      if (!modal) return;
      modal.classList.remove('active');
      modal.hidden = true;
      modal.style.display = 'none';
    }

    function cancelMapDraw() {
      mapDrawMode = null;
      mapDrawPoints = [];
      mapDrawMouseLatLng = null;
      pendingShapeRing = null;
      mapDrawLastClickAt = 0;
      mapDrawLastClickLatLng = null;
      setMapDrawDoubleClickZoom(true);
      clearMapDrawPreview();
      setMapDrawUi();
      hideAppPromptModal('shape-save-modal');
      try { hideDrawModeChooser(); } catch (eH) {}
    }

    // ========== WEATHER RADAR (RainViewer â€” last hour, ~5 min steps) ==========
    var mapRadarActive = false;
    var radarState = {
      host: '',
      frames: [],       // native + mid-blend steps for smoother 5-min feel
      idx: 0,
      front: 0,         // which buffer is currently visible (0|1)
      layers: [null, null], // A/B tile buffers
      timer: null,
      busy: false,
      latestTime: null,
      pausedHeavy: null
    };
    var RADAR_CROSSFADE_MS = 520;  // smooth opacity crossfade between steps
    var RADAR_DWELL_MS = 120;      // brief settle after fade (keeps motion fluid)
    var RADAR_HOLD_MS = 2000;      // pause on latest scan (background loop timing)
    var RADAR_OPACITY = 0.72;
    var RADAR_API = 'https://api.rainviewer.com/public/weather-maps.json';
    var radarAnimRaf = null;

    function formatRadarClock(unixSec) {
      // Fixed two-line layout so the HUD width/height never jumps as minutes tick
      try {
        var d = new Date(unixSec * 1000);
        var datePart = d.toLocaleString('en-US', {
          timeZone: 'America/Chicago',
          weekday: 'short',
          month: 'short',
          day: '2-digit'
        });
        var timePart = d.toLocaleString('en-US', {
          timeZone: 'America/Chicago',
          hour: 'numeric',
          minute: '2-digit',
          hour12: true
        });
        return datePart + '\n' + timePart + ' CT';
      } catch (e) {
        return new Date(unixSec * 1000).toLocaleString();
      }
    }

    /** Hunt calendar is not today (past or future) â€” radar is always live current data */
    function isRadarOutsideHuntToday() {
      if (!selectedDate) return false;
      try {
        var days = typeof getDaysFromToday === 'function' ? getDaysFromToday(selectedDate) : 0;
        return days !== 0;
      } catch (e) {
        return false;
      }
    }

    function setRadarChromeActive(on) {
      var ctrl = document.getElementById('map-radar-control');
      var btn = document.getElementById('map-radar-toggle');
      if (ctrl) {
        ctrl.classList.toggle('radar-on', !!on);
        if (!on) ctrl.classList.remove('has-current-note');
      }
      if (btn) {
        btn.classList.toggle('active', !!on);
        btn.setAttribute('aria-pressed', on ? 'true' : 'false');
        btn.setAttribute('title', on
          ? 'Radar on â€” tap to stop'
          : 'Animated weather radar â€” last hour, ~5 min steps');
        // Keep SVG icon; sweep animates via CSS when .radar-on
      }
    }

    /**
     * Forward-facing UI: date + time only.
     * Frame / scan meta stays internal (radarState) â€” never shown in the HUD.
     */
    function setRadarUiClock(unixSec) {
      var clock = document.getElementById('map-radar-clock');
      var ctrl = document.getElementById('map-radar-control');
      var note = document.getElementById('map-radar-current-note');
      if (clock) {
        if (!unixSec) {
          clock.textContent = 'â€”';
        } else {
          clock.textContent = formatRadarClock(unixSec);
        }
      }
      // Past/future hunt date: fixed "Radar is current" line (size reserved via CSS class once)
      var showNote = !!(unixSec && isRadarOutsideHuntToday());
      if (ctrl) ctrl.classList.toggle('has-current-note', showNote);
      if (note) note.textContent = 'Radar is current';
    }

    function radarTileUrlFromPath(path) {
      // RainViewer: host + path + /256/{z}/{x}/{y}/{color}/{options}.png
      return radarState.host + path + '/256/{z}/{x}/{y}/2/1_1.png';
    }

    /**
     * RainViewer past frames are ~10 min apart. Insert mid steps (~5 min clock)
     * that crossfade previous+next tiles so motion is smoother without extra API load.
     */
    function expandRadarFramesToFiveMin(nativeFrames) {
      var out = [];
      if (!nativeFrames || !nativeFrames.length) return out;
      for (var i = 0; i < nativeFrames.length; i++) {
        var cur = nativeFrames[i];
        out.push({
          time: cur.time,
          path: cur.path,
          blend: false,
          isLatest: i === nativeFrames.length - 1
        });
        if (i < nativeFrames.length - 1) {
          var nxt = nativeFrames[i + 1];
          var midT = Math.round((cur.time + nxt.time) / 2); // ~5 min when source is 10 min
          out.push({
            time: midT,
            path: nxt.path,       // primary path for buffer B
            pathPrev: cur.path,   // previous for blend A
            blend: true,
            isLatest: false
          });
        }
      }
      return out;
    }

    function makeRadarTileLayer(zIndex) {
      var phone = (typeof isPhoneLayout === 'function' && isPhoneLayout());
      return L.tileLayer('', {
        opacity: 0,
        zIndex: zIndex != null ? zIndex : 380,
        maxZoom: 12,
        maxNativeZoom: 7,
        minZoom: 3,
        detectRetina: false,
        updateWhenIdle: true,
        updateWhenZooming: false,
        keepBuffer: phone ? 0 : 1,
        crossOrigin: true,
        className: 'radar-frame-layer',
        attribution: 'Radar Â© RainViewer / NWS'
      });
    }

    /**
     * Radar used to remove public-land / pin layers for tile performance, which
     * â€œclearedâ€ the map and could leave Max/Min + compass buried after restore.
     * Radar tiles now draw on top of everything â€” never strip the map.
     */
    function pauseHeavyMapLayersForRadar() {
      // no-op: keep all map overlays, pins, Max/Min, compass visible
      radarState.pausedHeavy = null;
    }

    function restoreHeavyMapLayersAfterRadar() {
      // no-op paired with pauseHeavyMapLayersForRadar
      radarState.pausedHeavy = null;
      try {
        if (typeof clearMapPopupStackingState === 'function') clearMapPopupStackingState();
        if (typeof ensureMapBottomBarVisible === 'function') ensureMapBottomBarVisible();
      } catch (eRest) {}
    }

    function clearRadarTimer() {
      if (radarState.timer) {
        clearTimeout(radarState.timer);
        radarState.timer = null;
      }
      if (radarAnimRaf != null) {
        try { cancelAnimationFrame(radarAnimRaf); } catch (eR) {}
        radarAnimRaf = null;
      }
    }

    function destroyRadarLayers() {
      if (!map) return;
      radarState.layers.forEach(function(ly, i) {
        if (ly) {
          try { map.removeLayer(ly); } catch (e) {}
          radarState.layers[i] = null;
        }
      });
      radarState.front = 0;
    }

    function stopMapRadar() {
      mapRadarActive = false;
      clearRadarTimer();
      radarState.busy = false;
      radarState.frames = [];
      radarState.idx = 0;
      destroyRadarLayers();
      restoreHeavyMapLayersAfterRadar();
      setRadarChromeActive(false);
      setRadarUiClock(null);
      // Ensure map chrome (Max/Min, compass/wind, bottom bar) is never left buried
      try {
        if (typeof clearMapPopupStackingState === 'function') clearMapPopupStackingState();
        if (typeof ensureMapBottomBarVisible === 'function') ensureMapBottomBarVisible();
      } catch (eStopChrome) {}
    }
    window.stopMapRadar = stopMapRadar;

    function scheduleRadarNext(delay) {
      clearRadarTimer();
      radarState.timer = setTimeout(function() {
        radarState.timer = null;
        if (!mapRadarActive) return;
        radarState.idx = (radarState.idx + 1) % radarState.frames.length;
        showRadarFrame(radarState.idx);
      }, delay);
    }

    function waitLayerLoad(layer, done) {
      var settled = false;
      function finish() {
        if (settled) return;
        settled = true;
        done();
      }
      var to = setTimeout(finish, 850);
      try {
        layer.once('load', function() {
          clearTimeout(to);
          finish();
        });
      } catch (e) {
        clearTimeout(to);
        finish();
      }
      setTimeout(function() {
        try {
          if (layer._loading === false || layer._tilesToLoad === 0) {
            clearTimeout(to);
            finish();
          }
        } catch (e2) {}
      }, 70);
    }

    /** Ease-in-out cubic for soft opacity transitions */
    function radarEase(t) {
      return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
    }

    /**
     * Smoothly crossfade layerB in over layerA (or reverse).
     * Keeps only 2 tile layers; feels less "tick" and more continuous.
     */
    function crossfadeRadarLayers(fromLayer, toLayer, ms, done) {
      if (!fromLayer || !toLayer) {
        if (done) done();
        return;
      }
      var t0 = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      var from0 = typeof fromLayer.options.opacity === 'number' ? fromLayer.options.opacity : RADAR_OPACITY;
      try { from0 = fromLayer.options.opacity != null ? Number(fromLayer.options.opacity) : from0; } catch (e0) {}
      toLayer.setOpacity(0);

      function step(now) {
        if (!mapRadarActive) {
          radarAnimRaf = null;
          return;
        }
        var t = Math.min(1, (now - t0) / ms);
        var e = radarEase(t);
        try {
          toLayer.setOpacity(RADAR_OPACITY * e);
          fromLayer.setOpacity(from0 * (1 - e));
        } catch (e1) {}
        if (t < 1) {
          radarAnimRaf = requestAnimationFrame(step);
        } else {
          radarAnimRaf = null;
          try {
            toLayer.setOpacity(RADAR_OPACITY);
            fromLayer.setOpacity(0);
          } catch (e2) {}
          if (done) done();
        }
      }
      radarAnimRaf = requestAnimationFrame(step);
    }

    /**
     * Show one animation step with a smooth crossfade into the next radar image.
     * Mid ~5-min steps still use blended timing; UI only updates the clock.
     */
    function showRadarFrame(i) {
      if (!mapRadarActive || !map || !radarState.frames.length) return;
      if (radarState.busy) return;
      radarState.busy = true;
      radarState.idx = i;
      var frame = radarState.frames[i];
      var isLatest = !!frame.isLatest || (i === radarState.frames.length - 1 && !frame.blend);
      // UI: date + time only (no frame counts / scan notes)
      setRadarUiClock(frame.time);

      var layerA = radarState.layers[0];
      var layerB = radarState.layers[1];
      if (!layerA || !layerB) {
        radarState.busy = false;
        return;
      }

      function afterShown() {
        if (!mapRadarActive) return;
        radarState.busy = false;
        var delay = isLatest ? RADAR_HOLD_MS : RADAR_DWELL_MS;
        scheduleRadarNext(delay);
      }

      // Which buffer is currently visible?
      var front = radarState.front || 0;
      var back = 1 - front;
      var frontLayer = radarState.layers[front];
      var backLayer = radarState.layers[back];

      try {
        // Target image: native scan path, or mid-step blends toward next path
        var targetPath = frame.path;
        backLayer.setUrl(radarTileUrlFromPath(targetPath));
        waitLayerLoad(backLayer, function() {
          if (!mapRadarActive) return;
          // First frame: just fade in (nothing to crossfade from)
          var frontOp = 0;
          try { frontOp = Number(frontLayer.options.opacity) || 0; } catch (eF) {}
          if (frontOp < 0.05 && i === 0) {
            crossfadeRadarLayers(frontLayer, backLayer, Math.min(360, RADAR_CROSSFADE_MS), function() {
              radarState.front = back;
              afterShown();
            });
          } else {
            crossfadeRadarLayers(frontLayer, backLayer, RADAR_CROSSFADE_MS, function() {
              radarState.front = back;
              afterShown();
            });
          }
        });
      } catch (eUrl) {
        radarState.busy = false;
        scheduleRadarNext(RADAR_DWELL_MS);
      }
    }

    function startMapRadar() {
      ensureMap().then(function(m) {
        if (!m) return;
        if (mapDrawMode) cancelMapDraw();
        if (typeof gpsTrackActive !== 'undefined' && gpsTrackActive && typeof stopGpsTrack === 'function') {
          try { stopGpsTrack(); } catch (eT) {}
        }
        if (mapRadarActive) {
          stopMapRadar();
          return;
        }

        mapRadarActive = true;
        setRadarChromeActive(true);
        setRadarUiClock(null);

        // Do NOT strip map overlays / pins / chrome â€” radar paints on top only
        pauseHeavyMapLayersForRadar();
        // Close menus only; leave map dots, lands, Max/Min, compass alone
        if (map.closePopup) try { map.closePopup(); } catch (eP) {}
        try {
          if (typeof clearMapPopupStackingState === 'function') clearMapPopupStackingState();
        } catch (eStack0) {}

        destroyRadarLayers();
        // zIndex high so frames sit above basemap + land fills, not remove them
        radarState.layers[0] = makeRadarTileLayer(380).addTo(map);
        radarState.layers[1] = makeRadarTileLayer(381).addTo(map);
        radarState.front = 0;

        fetch(RADAR_API, { cache: 'no-store' })
          .then(function(res) {
            if (!res.ok) throw new Error('Radar API ' + res.status);
            return res.json();
          })
          .then(function(data) {
            if (!mapRadarActive) return;
            radarState.host = (data && data.host) || 'https://tilecache.rainviewer.com';
            var past = (data && data.radar && data.radar.past) ? data.radar.past.slice() : [];
            if (!past.length) throw new Error('No radar frames');

            // Prefer last ~hour of native (~10 min) scans, then expand to ~5 min steps
            var newest = past[past.length - 1].time;
            var cutoff = newest - 60 * 60;
            var hour = past.filter(function(f) { return f && f.time >= cutoff && f.path; });
            if (hour.length < 2) hour = past.slice(-Math.min(past.length, 12));
            radarState.frames = expandRadarFramesToFiveMin(hour);
            radarState.latestTime = hour[hour.length - 1].time;
            radarState.idx = 0;

            // Internal only â€” not shown in HUD
            try {
              console.debug('[radar] steps=' + radarState.frames.length +
                ' latest=' + (radarState.latestTime ? formatRadarClock(radarState.latestTime) : '?'));
            } catch (eDbg) {}

            setRadarUiClock(radarState.frames[0].time);
            showRadarFrame(0);
          })
          .catch(function(err) {
            console.error('Radar failed:', err);
            if (typeof showAppCopyToast === 'function') {
              showAppCopyToast('<span class="act">Radar failed</span><br>Could not load RainViewer frames. Check connection and retry.');
            }
            stopMapRadar();
          });
      });
    }

    function toggleMapRadar() {
      if (mapRadarActive) stopMapRadar();
      else startMapRadar();
    }
    window.toggleMapRadar = toggleMapRadar;
    window.startMapRadar = startMapRadar;

    function clearTempMeasure() {
      if (tempMeasureLayer && map) {
        try { map.removeLayer(tempMeasureLayer); } catch (eTm) {}
      }
      tempMeasureLayer = null;
    }
    window.clearTempMeasure = clearTempMeasure;

    function showTempMeasure(points, distanceMi) {
      clearTempMeasure();
      if (!map || !points || points.length < 2) return;
      try {
        var latlngs = points.map(function(p) { return [p.lat, p.lng]; });
        var halo = L.polyline(latlngs, {
          color: MEASURE_LINE_HALO,
          weight: 7,
          opacity: 0.95,
          dashArray: '7 7',
          lineCap: 'round',
          lineJoin: 'round',
          interactive: false
        });
        var line = L.polyline(latlngs, {
          color: MEASURE_LINE_COLOR,
          weight: 3.5,
          opacity: 1,
          dashArray: '7 7',
          lineCap: 'round',
          lineJoin: 'round',
          interactive: false
        });
        var layers = [halo, line];
        // Endpoint + intermediate dots: dark fill, thin light border
        points.forEach(function(p) {
          layers.push(L.circleMarker([p.lat, p.lng], {
            radius: 5,
            color: MEASURE_LINE_HALO,
            weight: 2,
            fillColor: MEASURE_LINE_COLOR,
            fillOpacity: 1,
            interactive: false
          }));
        });
        var mid = points[Math.floor(points.length / 2)];
        var labelTxt = formatMiles(distanceMi);
        var label = L.marker([mid.lat, mid.lng], {
          interactive: false,
          keyboard: false,
          zIndexOffset: 5000,
          icon: L.divIcon({
            className: 'temp-measure-label',
            html: '<div class="tml-box">' + labelTxt + '</div>',
            // Non-zero size so Leaflet does not collapse the label on reflow (#26)
            iconSize: [120, 32],
            iconAnchor: [60, 40]
          })
        });
        layers.push(label);
        tempMeasureLayer = L.layerGroup(layers).addTo(map);
      } catch (eShow) {
        tempMeasureLayer = null;
      }
    }

    function startMapMeasure() {
      ensureMap().then(function(m) {
        if (!m) return;
        if (mapRadarActive) stopMapRadar();
        if (gpsTrackActive) stopGpsTrack(); // save track if long enough
        clearTempMeasure();
        if (mapDrawMode === 'measure') {
          cancelMapDraw();
          return;
        }
        mapDrawMode = 'measure';
        mapDrawPoints = [];
        mapDrawMouseLatLng = null;
        mapDrawLastClickAt = 0;
        mapDrawLastClickLatLng = null;
        setMapDrawDoubleClickZoom(false);
        if (map) map.closePopup();
        clearMapDot();
        refreshMapDrawPreview();
        setMapDrawUi();
      });
    }
    window.startMapMeasure = startMapMeasure;

    /** Remember last Draw mode so next open defaults to Shape or Line. */
    var LAST_DRAW_KIND_KEY = 'reg_slayer_last_draw_kind';
    var lastDrawKind = 'shape';
    try {
      var _ldk = localStorage.getItem(LAST_DRAW_KIND_KEY);
      if (_ldk === 'line' || _ldk === 'shape') lastDrawKind = _ldk;
    } catch (eLdk) {}

    function persistLastDrawKind(kind) {
      lastDrawKind = (kind === 'line') ? 'line' : 'shape';
      try { localStorage.setItem(LAST_DRAW_KIND_KEY, lastDrawKind); } catch (eP) {}
    }
    function currentDrawKind() {
      if (mapDrawMode === 'drawline') return 'line';
      if (mapDrawMode === 'draw') return 'shape';
      return lastDrawKind || 'shape';
    }
    function hideDrawModeChooser() {
      var el = document.getElementById('draw-mode-chooser');
      if (el) el.classList.remove('open');
    }
    function isDrawModeChooserOpen() {
      var el = document.getElementById('draw-mode-chooser');
      return !!(el && el.classList.contains('open'));
    }
    function syncDrawModeChooserHighlight() {
      var el = document.getElementById('draw-mode-chooser');
      if (!el) return;
      var cur = currentDrawKind();
      el.querySelectorAll('button[data-draw-kind]').forEach(function(btn) {
        var k = btn.getAttribute('data-draw-kind');
        btn.classList.toggle('is-active', k === cur);
        btn.setAttribute('aria-pressed', k === cur ? 'true' : 'false');
      });
    }
    function showDrawModeChooser() {
      var btn = document.getElementById('mdt-draw');
      var el = document.getElementById('draw-mode-chooser');
      if (!el) {
        el = document.createElement('div');
        el.id = 'draw-mode-chooser';
        el.className = 'draw-mode-chooser';
        el.setAttribute('role', 'group');
        el.setAttribute('aria-label', 'Draw mode');
        el.innerHTML =
          '<button type="button" data-draw-kind="shape" onclick="event.stopPropagation();beginMapDrawMode(\'shape\')">Shape</button>' +
          '<button type="button" data-draw-kind="line" onclick="event.stopPropagation();beginMapDrawMode(\'line\')">Line</button>';
        document.body.appendChild(el);
      }
      if (!btn) {
        el.classList.add('open');
        syncDrawModeChooserHighlight();
        return;
      }
      var r = btn.getBoundingClientRect();
      el.style.left = Math.max(4, r.left + r.width / 2 - 54) + 'px';
      el.style.bottom = Math.max(8, window.innerHeight - r.top + 6) + 'px';
      el.style.top = 'auto';
      el.classList.add('open');
      syncDrawModeChooserHighlight();
    }
    function startMapDrawShape() {
      // Second click on Draw: dismiss chooser + stop draw mode
      if (mapDrawMode === 'draw' || mapDrawMode === 'drawline' || isDrawModeChooserOpen()) {
        if (mapDrawMode === 'draw' || mapDrawMode === 'drawline') {
          try { cancelMapDraw(); } catch (eC) {}
        }
        hideDrawModeChooser();
        return;
      }
      // Open: start last-used mode immediately, show chooser with it highlighted
      beginMapDrawMode(lastDrawKind || 'shape', { keepChooser: true });
    }
    /**
     * @param {'shape'|'line'} kind
     * @param {{ keepChooser?: boolean }} [opts]
     */
    function beginMapDrawMode(kind, opts) {
      opts = opts || {};
      var keepChooser = !!opts.keepChooser;
      persistLastDrawKind(kind);
      if (!keepChooser) {
        // Switching from the popup still keeps it open so the new mode stays highlighted
        keepChooser = isDrawModeChooserOpen();
      }
      ensureMap().then(function(m) {
        if (!m) return;
        if (mapRadarActive) stopMapRadar();
        if (gpsTrackActive) stopGpsTrack();
        if (typeof clearTempMeasure === 'function') clearTempMeasure();
        mapDrawMode = (kind === 'line') ? 'drawline' : 'draw';
        mapDrawPoints = [];
        mapDrawMouseLatLng = null;
        mapDrawLastClickAt = 0;
        mapDrawLastClickLatLng = null;
        setMapDrawDoubleClickZoom(false);
        if (map) map.closePopup();
        clearMapDot();
        refreshMapDrawPreview();
        setMapDrawUi();
        if (keepChooser) showDrawModeChooser();
        else hideDrawModeChooser();
      });
    }
    window.startMapDrawShape = startMapDrawShape;
    window.beginMapDrawMode = beginMapDrawMode;
    window.hideDrawModeChooser = hideDrawModeChooser;
    window.showDrawModeChooser = showDrawModeChooser;
    document.addEventListener('click', function(ev) {
      var ch = document.getElementById('draw-mode-chooser');
      if (!ch || !ch.classList.contains('open')) return;
      if (ch.contains(ev.target)) return;
      if (ev.target && ev.target.closest && ev.target.closest('#mdt-draw')) return;
      // Outside click only hides the chooser; draw mode keeps running with last choice
      hideDrawModeChooser();
    });
    window.undoMapDrawVertex = undoMapDrawVertex;
    window.cancelMapDraw = cancelMapDraw;

    /**
     * End the current measure line or finish the shape.
     * Called by the Finish button or double-click.
     */
    function finishMapDraw() {
      if (!mapDrawMode) return;
      mapDrawLastClickAt = 0;
      mapDrawLastClickLatLng = null;

      if (mapDrawMode === 'measure') {
        if (mapDrawPoints.length < 2) {
          alert('Add at least two points to measure a distance, then double-click, tap a point again, or press Finish.');
          return;
        }
        var total = pathDistanceMiles(mapDrawPoints);
        var pts = mapDrawPoints.map(function(p) { return { lat: p.lat, lng: p.lng }; });
        // Ephemeral only â€” next map click clears it (no manual delete)
        showTempMeasure(pts, total);
        showAppCopyToast(
          '<span class="act">Distance: ' + formatMiles(total) + '</span><br>' +
          'Tap the map again to clear this measurement.'
        );
        mapDrawMode = null;
        mapDrawPoints = [];
        mapDrawMouseLatLng = null;
        setMapDrawDoubleClickZoom(true);
        clearMapDrawPreview();
        setMapDrawUi();
        return;
      }
      if (mapDrawMode === 'drawline') {
        if (mapDrawPoints.length < 2) {
          alert('Add at least two points for a line, then double-click, tap a point again, or press Finish.');
          return;
        }
        var totalL = pathDistanceMiles(mapDrawPoints);
        var ptsL = mapDrawPoints.map(function(p) { return { lat: p.lat, lng: p.lng }; });
        mapDrawMode = null;
        mapDrawPoints = [];
        mapDrawMouseLatLng = null;
        setMapDrawDoubleClickZoom(true);
        clearMapDrawPreview();
        setMapDrawUi();
        // Save as measured path kind=line (not hunt area)
        if (typeof saveMeasuredPath === 'function') {
          saveMeasuredPath(ptsL, totalL, {
            kind: 'line',
            name: 'Drawn line',
            color: '#e59a18',
            weight: 4
          });
        }
        showAppCopyToast('<span class="act">Line saved</span><br>' + formatMiles(totalL) + ' â€” tap line to edit color/width/notes.');
        return;
      }
      if (mapDrawMode === 'draw') {
        if (mapDrawPoints.length < 3) {
          alert('Add at least three points to form a shape, then double-click or press Finish.');
          return;
        }
        // Build closed ring [lat,lng]
        var ring = mapDrawPoints.map(function(p) { return [p.lat, p.lng]; });
        var first = ring[0], last = ring[ring.length - 1];
        if (first[0] !== last[0] || first[1] !== last[1]) ring.push([first[0], first[1]]);
        pendingShapeRing = ring;
        openShapeSaveModal(ring);
        // Leave draw mode active until save/cancel so user can still cancel points if they dismiss modal without saving
      }
    }
    window.finishMapDraw = finishMapDraw;

    var shapeColorSlot = 'line'; // line | fill
    function setShapeColorSlot(slot) {
      shapeColorSlot = (slot === 'fill') ? 'fill' : 'line';
      var bL = document.getElementById('shape-slot-line');
      var bF = document.getElementById('shape-slot-fill');
      if (bL) bL.classList.toggle('is-active', shapeColorSlot === 'line');
      if (bF) bF.classList.toggle('is-active', shapeColorSlot === 'fill');
      var lineH = document.getElementById('shape-line-color');
      var fillH = document.getElementById('shape-fill-color');
      var actH = document.getElementById('shape-active-color');
      var val = shapeColorSlot === 'fill'
        ? ((fillH && fillH.value) || '#e59a18')
        : ((lineH && lineH.value) || '#e59a18');
      if (actH) actH.value = val;
      var cp = document.getElementById('cp-shape');
      if (cp && typeof setColorPickerValue === 'function') {
        setColorPickerValue(cp, val, { silent: true });
      }
    }
    window.setShapeColorSlot = setShapeColorSlot;

    function openShapeSaveModal(ring) {
      var c = ringCentroid(ring);
      var landInfo = c ? resolveLandContextAtPoint(c.lat, c.lng) : null;
      var meta = document.getElementById('shape-save-meta');
      if (meta) {
        var perim = 0;
        for (var i = 1; i < ring.length; i++) {
          perim += haversineMiles(ring[i - 1][0], ring[i - 1][1], ring[i][0], ring[i][1]);
        }
        var landLine = landInfo
          ? ('Rules will follow: <strong style="color:var(--accent);">' + escHtml(landInfo.label) + '</strong> Â· Zone ' + escHtml(landInfo.zone) + '.')
          : 'Rules will follow the statewide deer zone under the shape center.';
        meta.innerHTML = landLine + ' Perimeter ~' + formatMiles(perim) + '.';
      }
      var nameInp = document.getElementById('shape-name-input');
      if (nameInp) {
        nameInp.value = landInfo && landInfo.unitName
          ? (landInfo.unitName + ' â€” custom area')
          : '';
      }
      var fillChk = document.getElementById('shape-fill-enabled');
      var permChk = document.getElementById('shape-permission-chk');
      if (permChk) permChk.checked = false;
      if (typeof initAllColorPickers === 'function') initAllColorPickers();
      var lineH = document.getElementById('shape-line-color');
      var fillH = document.getElementById('shape-fill-color');
      if (lineH) lineH.value = '#e59a18';
      if (fillH) fillH.value = '#e59a18';
      shapeColorSlot = 'line';
      setShapeColorSlot('line');
      // Route shared picker â†’ line/fill hidden fields
      var act = document.getElementById('shape-active-color');
      if (act && !act._shapeSlotWired) {
        act._shapeSlotWired = true;
        act.addEventListener('change', function() {
          var v = act.value;
          if (!v) return;
          if (shapeColorSlot === 'fill') {
            var f = document.getElementById('shape-fill-color');
            if (f) f.value = v;
          } else {
            var l = document.getElementById('shape-line-color');
            if (l) l.value = v;
          }
        });
      }
      // Disable fill slot chrome when fill unchecked
      if (fillChk && !fillChk._wiredFillSlot) {
        fillChk._wiredFillSlot = true;
        fillChk.addEventListener('change', function() {
          var bF = document.getElementById('shape-slot-fill');
          if (bF) {
            bF.disabled = !fillChk.checked;
            bF.style.opacity = fillChk.checked ? '1' : '0.45';
          }
          if (!fillChk.checked && shapeColorSlot === 'fill') setShapeColorSlot('line');
        });
      }
      if (fillChk) {
        var bF0 = document.getElementById('shape-slot-fill');
        if (bF0) {
          bF0.disabled = !fillChk.checked;
          bF0.style.opacity = fillChk.checked ? '1' : '0.45';
        }
      }
      showAppPromptModal('shape-save-modal');
      // Name is optional â€” don't force focus/keyboard
    }

    function cancelShapeSaveModal() {
      hideAppPromptModal('shape-save-modal');
      pendingShapeRing = null;
      // Cancel clears the entire drawing
      cancelMapDraw();
    }
    window.cancelShapeSaveModal = cancelShapeSaveModal;

    /**
     * Infer land type / unit under a point so custom areas inherit real-world rules.
     */
    function resolveLandContextAtPoint(lat, lng) {
      var zoneInfo = detectBoundaryAndZone(lat, lng);
      var zone = (zoneInfo && zoneInfo.zone) || 'A';
      var best = null;

      // Prefer official public-land polygon under the point
      if (adcnrLandsData && adcnrLandsData.layers) {
        var layers = adcnrLandsData.layers || [];
        for (var li = 0; li < layers.length; li++) {
          var layer = layers[li];
          if (!layer || layer.drawOnMap === false || layer.key === 'nps' || layer.key === 'usfs') continue;
          var feats = layer.features || [];
          for (var fi = 0; fi < feats.length; fi++) {
            var attrs = feats[fi].attributes || {};
            if (!mayDrawHuntableFeature(layer, attrs)) continue;
            var rings = feats[fi].geometry && feats[fi].geometry.rings;
            if (!rings) continue;
            var inside = false;
            for (var ri = 0; ri < rings.length; ri++) {
              if (pointInRing(lng, lat, rings[ri])) { inside = true; break; }
            }
            if (!inside) continue;
            var uname = featureDisplayName(layer, attrs) || layer.label || 'Public land';
            // Prefer more specific units (WMA over large forests already skipped)
            var rank = (layer.key === 'wma' || layer.key === 'soa' || layer.key === 'pdha') ? 3
              : (layer.key === 'nwr' || layer.key === 'usace') ? 2
              : (layer.key === 'tva' || layer.key === 'foreverWild') ? 1 : 0;
            if (!best || rank >= best.rank) {
              best = {
                rank: rank,
                landSource: layer.key,
                type: layer.typeLabel || layer.label || 'Public',
                unitName: uname,
                label: uname + ' (' + (layer.typeLabel || layer.key) + ')',
                zone: zone,
                notes: publicLandRuleNotes(layer, attrs),
                gisAttrs: attrs
              };
            }
          }
        }
      }

      if (best) return best;

      // Built-in named areas near point (fallback)
      if (zoneInfo && zoneInfo.type && zoneInfo.type !== 'Statewide') {
        return {
          rank: 0,
          landSource: zoneInfo.type === 'Refuge' ? 'nwr' : (zoneInfo.type === 'WMA' ? 'wma' : 'custom'),
          type: zoneInfo.type,
          unitName: zoneInfo.name,
          label: zoneInfo.name + ' Â· Zone ' + zone,
          zone: zone,
          notes: zoneInfo.desc || ('Deer rules for Zone ' + zone + ' apply. Confirm landowner / posted rules.'),
          gisAttrs: null
        };
      }

      return {
        rank: 0,
        landSource: 'custom',
        type: 'Custom Area',
        unitName: null,
        label: 'Statewide Zone ' + zone + ' (public/private rules for that zone)',
        zone: zone,
        notes: 'Custom drawn area. Inherits Zone ' + zone + ' deer seasons for the selected weapon. Confirm landowner / public-land rules before hunting.',
        gisAttrs: null
      };
    }

    function loadCustomAreasFromStorage() {
      try {
        var raw = localStorage.getItem(CUSTOM_AREAS_KEY);
        if (!raw) return [];
        var arr = JSON.parse(raw);
        return Array.isArray(arr) ? arr : [];
      } catch (e) { return []; }
    }

    // ----- Persistent measured / drawn lines (hover for stats) -----
    function loadMeasuredPathsFromStorage() {
      try {
        var raw = localStorage.getItem(MEASURED_PATHS_KEY);
        if (!raw) return [];
        var arr = JSON.parse(raw);
        return Array.isArray(arr) ? arr : [];
      } catch (e) { return []; }
    }

    function saveMeasuredPathsToStorage(paths) {
      try {
        localStorage.setItem(MEASURED_PATHS_KEY, JSON.stringify(paths || []));
      } catch (e) {
        console.warn('Could not save measured paths', e);
      }
    }

    function formatElevFt(ft) {
      if (ft == null || isNaN(ft)) return 'â€”';
      var n = Math.round(ft);
      var sign = n > 0 ? '+' : '';
      return sign + n.toLocaleString() + ' ft';
    }

    function formatAddedDate(iso) {
      try {
        var d = iso ? new Date(iso) : new Date();
        if (isNaN(d.getTime())) d = new Date();
        return d.toLocaleDateString(undefined, {
          year: 'numeric', month: 'short', day: 'numeric'
        }) + ' Â· ' + d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
      } catch (e) {
        return 'Unknown date';
      }
    }

    function formatDurationMs(ms) {
      if (ms == null || isNaN(ms) || ms < 0) return 'â€”';
      var sec = Math.floor(ms / 1000);
      var h = Math.floor(sec / 3600);
      var m = Math.floor((sec % 3600) / 60);
      var s = sec % 60;
      if (h > 0) return h + 'h ' + m + 'm';
      if (m > 0) return m + 'm ' + s + 's';
      return s + 's';
    }

    function formatClock(msOrIso) {
      try {
        var d = typeof msOrIso === 'number' ? new Date(msOrIso) : new Date(msOrIso);
        if (isNaN(d.getTime())) return 'â€”';
        return d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit', second: '2-digit' });
      } catch (e) { return 'â€”'; }
    }

    /**
     * Nearest location along a timed path to a map latlng.
     * Returns distance-from-start, elapsed time, and clock time at that point.
     */
    function nearestAlongTimedPath(points, latlng) {
      if (!points || points.length < 2 || !latlng) return null;
      var best = null;
      var distAlong = 0;
      for (var i = 1; i < points.length; i++) {
        var a = points[i - 1], b = points[i];
        var segMi = haversineMiles(a.lat, a.lng, b.lat, b.lng);
        // Project point onto segment (rough geographic lerp by lat/lng)
        var abLat = b.lat - a.lat, abLng = b.lng - a.lng;
        var ab2 = abLat * abLat + abLng * abLng;
        var t = 0;
        if (ab2 > 1e-18) {
          t = ((latlng.lat - a.lat) * abLat + (latlng.lng - a.lng) * abLng) / ab2;
          t = Math.max(0, Math.min(1, t));
        }
        var pLat = a.lat + t * abLat;
        var pLng = a.lng + t * abLng;
        var d = haversineMiles(latlng.lat, latlng.lng, pLat, pLng);
        var along = distAlong + segMi * t;
        var tA = a.t != null ? a.t : null;
        var tB = b.t != null ? b.t : null;
        var elapsed = null;
        var clock = null;
        if (tA != null && tB != null) {
          clock = tA + (tB - tA) * t;
          var t0 = points[0].t != null ? points[0].t : tA;
          elapsed = clock - t0;
        } else if (tA != null) {
          clock = tA;
          elapsed = points[0].t != null ? (tA - points[0].t) : 0;
        }
        // Interpolate elevation (meters) along the segment when samples exist
        var elevM = null;
        var elevA = a.elevM != null && !isNaN(a.elevM) ? a.elevM : null;
        var elevB = b.elevM != null && !isNaN(b.elevM) ? b.elevM : null;
        if (elevA != null && elevB != null) elevM = elevA + (elevB - elevA) * t;
        else if (elevA != null) elevM = elevA;
        else if (elevB != null) elevM = elevB;
        if (!best || d < best.d) {
          best = {
            d: d,
            distFromStartMi: along,
            elapsedMs: elapsed,
            clockMs: clock,
            lat: pLat,
            lng: pLng,
            elevM: elevM
          };
        }
        distAlong += segMi;
      }
      return best;
    }

    function measuredPathTooltipHtml(path, along) {
      var isTrack = path.kind === 'track';
      var titleColor = path.color || (isTrack ? '#f87171' : '#38bdf8');
      var title = escHtml(path.name || (isTrack ? 'GPS track' : 'Measured line'));
      var dist = path.distanceMi != null ? formatMiles(path.distanceMi) : formatMiles(pathDistanceMiles(path.points || []));
      var elevLine = 'Elevation: loadingâ€¦';
      if (path.elev) {
        var net = path.elev.netFt;
        var gain = path.elev.gainFt;
        var loss = path.elev.lossFt;
        var start = path.elev.startFt;
        var end = path.elev.endFt;
        elevLine =
          'Elevation change: <strong style="color:#fff;">' + formatElevFt(net) + ' net</strong>' +
          '<br><span style="color:#c5d0be;">Gain ' + formatElevFt(gain).replace('+','') +
          ' Â· Loss ' + formatElevFt(-Math.abs(loss || 0)).replace('+','') +
          (start != null && end != null
            ? ' Â· Start ' + Math.round(start) + ' ft â†’ End ' + Math.round(end) + ' ft'
            : '') + '</span>';
      } else if (path.elevError) {
        elevLine = 'Elevation: unavailable';
      }

      var durationLine = '';
      if (path.durationMs != null) {
        durationLine = '<div style="margin-top:3px;">Duration: <strong style="color:#fff;">' + formatDurationMs(path.durationMs) + '</strong></div>';
      }
      var speedLine = '';
      if (path.avgSpeedMph != null && !isNaN(path.avgSpeedMph)) {
        speedLine = '<div style="margin-top:3px;">Avg speed: <strong style="color:#fff;">' + path.avgSpeedMph.toFixed(1) + ' mph</strong></div>';
      }

      var alongHtml = '';
      var alongElevLine = '';
      try {
        if (along) {
          var elevAt = null;
          if (along.elevM != null && path.points[0] && path.points[0].elevM != null) {
            elevAt = formatElevDeltaFt((along.elevM - path.points[0].elevM) * 3.28084);
          } else if (path.elev && path.elev.netFt != null && path.distanceMi) {
            elevAt = formatElevDeltaFt(
              (along.distFromStartMi / Math.max(path.distanceMi, 1e-6)) * path.elev.netFt
            );
          }
          if (elevAt) {
            alongElevLine =
              '<div style="margin-top:2px;">Elev Î” from start: <strong style="color:#fff;">' +
              elevAt + '</strong></div>';
          }
        }
      } catch (eAl) {}
      if (along && isTrack) {
        alongHtml =
          '<div style="margin-top:8px;padding-top:6px;border-top:1px solid rgba(255,255,255,0.15);">' +
            '<div style="font-size:10px;color:#fca5a5;font-weight:800;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:3px;">At this point</div>' +
            '<div>From start: <strong style="color:#fff;">' + formatMiles(along.distFromStartMi) + '</strong></div>' +
            alongElevLine +
            (along.elapsedMs != null
              ? '<div style="margin-top:2px;">Time into track: <strong style="color:#fff;">' + formatDurationMs(along.elapsedMs) + '</strong></div>'
              : '') +
            (along.clockMs != null
              ? '<div style="margin-top:2px;">Clock: <strong style="color:#fff;">' + formatClock(along.clockMs) + '</strong></div>'
              : '') +
          '</div>';
      } else if (along && !isTrack) {
        alongHtml =
          '<div style="margin-top:8px;padding-top:6px;border-top:1px solid rgba(255,255,255,0.15);">' +
            '<div style="font-size:10px;color:#7dd3fc;font-weight:800;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:3px;">At this point</div>' +
            '<div>From start: <strong style="color:#fff;">' + formatMiles(along.distFromStartMi) + '</strong></div>' +
            alongElevLine +
          '</div>';
      }

      var notesHtml = path.notes
        ? '<div style="margin-top:6px;font-size:11px;color:#c5d0be;">' + escHtml(path.notes) + '</div>'
        : '';

      return (
        '<div style="min-width:180px;max-width:260px;line-height:1.4;">' +
          '<div style="font-weight:800;color:' + titleColor + ';margin-bottom:4px;">' + title + '</div>' +
          '<div>Distance: <strong style="color:#fff;">' + dist + '</strong></div>' +
          durationLine +
          speedLine +
          '<div style="margin-top:3px;">' + elevLine + '</div>' +
          '<div style="margin-top:5px;font-size:11px;color:#c5d0be;">Added: ' + escHtml(formatAddedDate(path.createdAt)) + '</div>' +
          notesHtml +
          alongHtml +
        '</div>'
      );
    }

    // ========== LIVE GPS TRACK (battery-friendly) ==========
    function gpsTrackElevDeltaFt(pts) {
      if (!pts || pts.length < 2) return null;
      var first = null, last = null;
      for (var i = 0; i < pts.length; i++) {
        if (pts[i].elevM != null && !isNaN(pts[i].elevM)) {
          if (first == null) first = pts[i].elevM;
          last = pts[i].elevM;
        }
      }
      if (first == null || last == null) return null;
      return (last - first) * 3.28084;
    }

    function formatElevDeltaFt(ft) {
      if (ft == null || isNaN(ft)) return 'â€”';
      var sign = ft > 0.5 ? '+' : (ft < -0.5 ? 'âˆ’' : '');
      var abs = Math.abs(ft);
      if (abs < 1) return '0 ft';
      return sign + Math.round(abs) + ' ft';
    }

    var trackHudDragOffset = null; // {left, bottom} when user dragged HUD
    function positionTrackLiveHud() {
      var hud = document.getElementById('map-track-live-hud');
      var trackBtn = document.getElementById('mdt-track');
      var bar = document.querySelector('.map-bottom-bar');
      if (!hud) return;
      if (!gpsTrackActive) {
        hud.hidden = true;
        hud.style.display = 'none';
        return;
      }
      hud.hidden = false;
      hud.style.display = 'block';
      // Docked just above the bottom toolbar (not behind / not on top of it) (#23)
      try {
        hud.style.position = 'fixed';
        hud.style.zIndex = '2147483005';
        if (trackHudDragOffset) {
          hud.style.left = trackHudDragOffset.left + 'px';
          hud.style.bottom = trackHudDragOffset.bottom + 'px';
          hud.style.top = 'auto';
          hud.style.transform = 'none';
        } else {
          var barRect = bar ? bar.getBoundingClientRect() : null;
          var tr = trackBtn ? trackBtn.getBoundingClientRect() : null;
          var left = tr ? (tr.left + tr.width / 2) : (window.innerWidth / 2);
          var barTop = barRect ? barRect.top : (window.innerHeight - 48);
          // Sit flush above the bar top edge
          var bottom = Math.max(8, window.innerHeight - barTop + 4);
          hud.style.left = left + 'px';
          hud.style.top = 'auto';
          hud.style.bottom = bottom + 'px';
          hud.style.transform = 'translateX(-50%)';
        }
      } catch (ePos) {}
    }
    function wireTrackLiveHudDrag() {
      var hud = document.getElementById('map-track-live-hud');
      var handle = document.getElementById('mtl-drag-handle') || hud;
      if (!hud || !handle || handle._wiredTrackDrag) return;
      handle._wiredTrackDrag = true;
      var dragging = false, startX = 0, startY = 0, origL = 0, origB = 0;
      function onDown(ev) {
        if (ev.target && ev.target.closest && ev.target.closest('.mtl-stop')) return;
        dragging = true;
        hud.classList.add('is-dragging');
        var pt = ev.touches ? ev.touches[0] : ev;
        startX = pt.clientX; startY = pt.clientY;
        var r = hud.getBoundingClientRect();
        origL = r.left;
        origB = window.innerHeight - r.bottom;
        ev.preventDefault();
      }
      function onMove(ev) {
        if (!dragging) return;
        var pt = ev.touches ? ev.touches[0] : ev;
        var dx = pt.clientX - startX;
        var dy = pt.clientY - startY;
        trackHudDragOffset = {
          left: Math.max(4, Math.min(window.innerWidth - 40, origL + dx)),
          bottom: Math.max(4, Math.min(window.innerHeight - 40, origB - dy))
        };
        positionTrackLiveHud();
      }
      function onUp() {
        dragging = false;
        hud.classList.remove('is-dragging');
      }
      handle.addEventListener('mousedown', onDown);
      handle.addEventListener('touchstart', onDown, { passive: false });
      window.addEventListener('mousemove', onMove);
      window.addEventListener('touchmove', onMove, { passive: false });
      window.addEventListener('mouseup', onUp);
      window.addEventListener('touchend', onUp);
    }

    function stopGpsTrackLiveTimer() {
      if (gpsTrackLiveTimer) {
        try { clearInterval(gpsTrackLiveTimer); } catch (eT) {}
        gpsTrackLiveTimer = null;
      }
    }

    function startGpsTrackLiveTimer() {
      stopGpsTrackLiveTimer();
      gpsTrackLiveTimer = setInterval(function() {
        if (!gpsTrackActive) {
          stopGpsTrackLiveTimer();
          return;
        }
        updateTrackButtonUi();
      }, 1000);
    }

    function updateTrackButtonUi() {
      var tools = document.getElementById('map-draw-tools');
      if (tools) tools.classList.toggle('tracking', !!gpsTrackActive);
      var trackBtn = document.getElementById('mdt-track');
      if (trackBtn) {
        trackBtn.classList.toggle('active', !!gpsTrackActive);
        trackBtn.setAttribute('aria-pressed', gpsTrackActive ? 'true' : 'false');
        trackBtn.title = gpsTrackActive ? 'Tracking â€” tap to stop' : 'Track';
      }
      var hud = document.getElementById('map-track-live-hud');
      if (!gpsTrackActive) {
        if (hud) {
          hud.hidden = true;
          hud.style.display = 'none';
        }
        stopGpsTrackLiveTimer();
        return;
      }
      positionTrackLiveHud();
      var dist = pathDistanceMiles(gpsTrackPoints);
      var elapsed = gpsTrackStartedAt ? (Date.now() - gpsTrackStartedAt) : 0;
      var elevFt = gpsTrackElevDeltaFt(gpsTrackPoints);
      var elDist = document.getElementById('mtl-dist');
      var elTime = document.getElementById('mtl-time');
      var elElev = document.getElementById('mtl-elev');
      if (elDist) elDist.textContent = formatMiles(dist);
      if (elTime) elTime.textContent = formatDurationMs(elapsed);
      if (elElev) elElev.textContent = formatElevDeltaFt(elevFt);
    }

    function refreshGpsTrackPreview() {
      if (!map || !mapDrawPreviewLayer) return;
      var pts = gpsTrackActive
        ? gpsTrackPoints
        : (gpsTrackPending && gpsTrackPending.points ? gpsTrackPending.points : null);
      var color = gpsTrackActive
        ? gpsTrackPreviewColor
        : ((gpsTrackPending && gpsTrackPending.color) || gpsTrackPreviewColor || '#d94136');
      if (pts && pts.length) {
        clearMapDrawPreview();
        if (pts.length >= 2) {
          var latlngs = pts.map(function(p) { return [p.lat, p.lng]; });
          L.polyline(latlngs, {
            color: color,
            weight: 4,
            opacity: 0.95,
            interactive: false,
            smoothFactor: 1.4,
            lineCap: 'round',
            lineJoin: 'round'
          }).addTo(mapDrawPreviewLayer);
          var last = pts[pts.length - 1];
          L.circleMarker([last.lat, last.lng], {
            radius: 6, color: '#fff', weight: 2, fillColor: color, fillOpacity: 1, interactive: false
          }).addTo(mapDrawPreviewLayer);
        } else if (pts.length === 1) {
          var p0 = pts[0];
          L.circleMarker([p0.lat, p0.lng], {
            radius: 6, color: '#fff', weight: 2, fillColor: color, fillOpacity: 1, interactive: false
          }).addTo(mapDrawPreviewLayer);
        }
      }
      updateTrackButtonUi();
    }

    function onGpsTrackPosition(pos) {
      if (!gpsTrackActive || !pos || !pos.coords) return;
      var lat = pos.coords.latitude;
      var lng = pos.coords.longitude;
      if (lat == null || lng == null || isNaN(lat) || isNaN(lng)) return;
      var now = Date.now();
      var accuracy = pos.coords.accuracy; // meters
      var elevM = pos.coords.altitude;
      if (elevM != null && isNaN(elevM)) elevM = null;
      // Reject very poor fixes to save junk points (and battery from thrashing)
      if (accuracy != null && accuracy > 80) return;

      userLat = lat;
      userLng = lng;
      if (map && gpsMarker) setGpsMarker(lat, lng);

      if (!gpsTrackPoints.length) {
        gpsTrackPoints.push({ lat: lat, lng: lng, t: now, elevM: elevM });
        gpsTrackLastAcceptedAt = now;
        refreshGpsTrackPreview();
        if (map) map.setView([lat, lng], Math.max(map.getZoom(), 15));
        return;
      }

      var last = gpsTrackPoints[gpsTrackPoints.length - 1];
      var dMi = haversineMiles(last.lat, last.lng, lat, lng);
      var dtMs = now - (last.t || gpsTrackLastAcceptedAt || now);
      var dtHr = dtMs / 3600000;

      // Instant speed check (mph) â€” auto-stop if faster than 30 mph
      if (dtMs > 800 && dMi > 0.001) {
        var speed = dMi / Math.max(dtHr, 1e-9);
        if (speed > GPS_TRACK_MAX_SPEED_MPH) {
          showAppCopyToast(
            '<span class="act">Track stopped</span><br>Speed over ' + GPS_TRACK_MAX_SPEED_MPH +
            ' mph detected (~' + speed.toFixed(0) + ' mph).'
          );
          stopGpsTrack({ auto: true, reason: 'speed' });
          return;
        }
      }

      // Battery-friendly: require min move OR enough time between points
      var timeOk = (now - gpsTrackLastAcceptedAt) >= GPS_TRACK_MIN_INTERVAL_MS;
      var moveOk = dMi >= GPS_TRACK_MIN_MOVE_MI;
      if (!timeOk && !moveOk) return;
      // If only time passed but we barely moved, skip (jitter)
      if (!moveOk && dMi < GPS_TRACK_MIN_MOVE_MI * 0.4) return;

      // Exponential average to smooth GPS jitter / jagged lines (#23)
      var alpha = 0.32;
      if (accuracy != null && accuracy < 12) alpha = 0.55;
      else if (accuracy != null && accuracy > 35) alpha = 0.22;
      var sLat = last.lat + (lat - last.lat) * alpha;
      var sLng = last.lng + (lng - last.lng) * alpha;
      // Light look-ahead blend with previous two points when available
      if (gpsTrackPoints.length >= 2) {
        var prev = gpsTrackPoints[gpsTrackPoints.length - 2];
        sLat = 0.15 * prev.lat + 0.5 * last.lat + 0.35 * sLat;
        sLng = 0.15 * prev.lng + 0.5 * last.lng + 0.35 * sLng;
      }
      var sElev = elevM;
      if (elevM != null && last.elevM != null && !isNaN(last.elevM)) {
        sElev = last.elevM + (elevM - last.elevM) * alpha;
      }
      gpsTrackPoints.push({ lat: sLat, lng: sLng, t: now, elevM: sElev });
      gpsTrackLastAcceptedAt = now;
      refreshGpsTrackPreview();

      // Gentle follow: only pan if point is near edge
      try {
        if (map && !map.getBounds().pad(-0.2).contains([lat, lng])) {
          map.panTo([lat, lng], { animate: true });
        }
      } catch (e) {}
    }

    function onGpsTrackError(err) {
      console.warn('GPS track error', err);
      if (!gpsTrackActive) return;
      if (err && err.code === 1) {
        showAppCopyToast('<span class="act">Location blocked</span><br>Allow location access to use Track.');
        stopGpsTrack({ auto: true, reason: 'denied', discard: gpsTrackPoints.length < 2 });
      } else {
        updateTrackButtonUi();
      }
    }

    function startGpsTrack() {
      if (!navigator.geolocation) {
        alert('Geolocation is not supported on this device/browser.');
        return;
      }
      // Finish any pending unsaved track first
      if (gpsTrackPending) {
        showAppCopyToast('<span class="act">Finish previous track</span><br>Save or delete the last track before starting a new one.');
        openTrackFinishModal();
        return;
      }
      // Stop measure/draw if running
      if (mapDrawMode) cancelMapDraw();

      ensureMap().then(function(m) {
        if (!m) {
          alert('Map is not ready yet.');
          return;
        }
        gpsTrackActive = true;
        gpsTrackPoints = [];
        gpsTrackStartedAt = Date.now();
        gpsTrackLastAcceptedAt = 0;
        gpsTrackPreviewColor = '#d94136';
        // Do not clear the map (dots / lands / chrome). Only dismiss open menus.
        if (map) {
          try { map.closePopup(); } catch (eCp) {}
        }
        try {
          if (typeof clearMapPopupStackingState === 'function') clearMapPopupStackingState();
          if (typeof ensureMapBottomBarVisible === 'function') ensureMapBottomBarVisible();
        } catch (eTrackChrome) {}

        try {
          gpsTrackWatchId = navigator.geolocation.watchPosition(
            onGpsTrackPosition,
            onGpsTrackError,
            {
              enableHighAccuracy: true, // better altitude + accuracy for elev Î”
              maximumAge: 4000,
              timeout: 20000
            }
          );
        } catch (e) {
          gpsTrackActive = false;
          alert('Could not start GPS tracking.');
          return;
        }

        if (userLat != null && userLng != null) {
          onGpsTrackPosition({
            coords: { latitude: userLat, longitude: userLng, accuracy: 30, altitude: null },
            timestamp: Date.now()
          });
        }
        startGpsTrackLiveTimer();
        updateTrackButtonUi();
        showAppCopyToast('<span class="act">Tracking started</span><br>Stats appear above the Track button. Tap <strong>Stop</strong> when done.');
      });
    }

    function openTrackFinishModal() {
      if (!gpsTrackPending) return;
      var meta = document.getElementById('track-finish-meta');
      var p = gpsTrackPending;
      if (meta) {
        meta.innerHTML =
          formatMiles(p.distanceMi) + ' Â· ' + formatDurationMs(p.durationMs) +
          (p.avgSpeedMph > 0.05 ? ' Â· ~' + p.avgSpeedMph.toFixed(1) + ' mph avg' : '') +
          (p.elevDeltaFt != null ? ' Â· Elev Î” ' + formatElevDeltaFt(p.elevDeltaFt) : '') +
          '<br>Name is optional. Save keeps the track; Delete discards it.';
      }
      var n = document.getElementById('track-finish-name');
      var c = document.getElementById('track-finish-color');
      if (n) n.value = p.defaultName || '';
      var col = p.color || '#d94136';
      if (c) c.value = col;
      if (typeof initAllColorPickers === 'function') initAllColorPickers();
      var cp = document.getElementById('cp-track-finish');
      if (cp && typeof setColorPickerValue === 'function') setColorPickerValue(cp, col);
      // Live-update preview color when picker changes
      if (c && !c._trackFinishWired) {
        c._trackFinishWired = true;
        c.addEventListener('change', function() {
          if (!gpsTrackPending) return;
          gpsTrackPending.color = c.value || '#d94136';
          refreshGpsTrackPreview();
        });
        c.addEventListener('input', function() {
          if (!gpsTrackPending) return;
          gpsTrackPending.color = c.value || '#d94136';
          refreshGpsTrackPreview();
        });
      }
      showAppPromptModal('track-finish-modal');
    }

    function confirmTrackFinishSave() {
      if (!gpsTrackPending) {
        hideAppPromptModal('track-finish-modal');
        return;
      }
      var nEl = document.getElementById('track-finish-name');
      var cEl = document.getElementById('track-finish-color');
      var name = (nEl && nEl.value) ? String(nEl.value).trim() : '';
      if (!name) name = gpsTrackPending.defaultName || 'GPS track';
      var color = (cEl && cEl.value) ? cEl.value : (gpsTrackPending.color || '#d94136');
      var wEl = document.getElementById('track-finish-weight');
      var weight = wEl ? parseInt(wEl.value, 10) : 5;
      if (isNaN(weight)) weight = 5;
      var p = gpsTrackPending;
      gpsTrackPending = null;
      clearMapDrawPreview();
      hideAppPromptModal('track-finish-modal');
      saveMeasuredPath(p.points, p.distanceMi, {
        kind: 'track',
        name: name,
        color: color,
        weight: weight,
        durationMs: p.durationMs,
        avgSpeedMph: p.avgSpeedMph,
        notes: p.notes || ''
      });
      showAppCopyToast(
        '<span class="act">Track saved</span><br>' +
        escHtml(name) + ' Â· ' + formatMiles(p.distanceMi) + ' Â· ' + formatDurationMs(p.durationMs)
      );
    }

    function confirmTrackFinishDelete() {
      gpsTrackPending = null;
      clearMapDrawPreview();
      hideAppPromptModal('track-finish-modal');
      showAppCopyToast('<span class="act">Track deleted</span><br>Recording discarded.');
    }
    window.confirmTrackFinishSave = confirmTrackFinishSave;
    window.confirmTrackFinishDelete = confirmTrackFinishDelete;

    function stopGpsTrack(opts) {
      opts = opts || {};
      if (!gpsTrackActive && !gpsTrackWatchId) {
        updateTrackButtonUi();
        return;
      }
      gpsTrackActive = false;
      stopGpsTrackLiveTimer();
      if (gpsTrackWatchId != null && navigator.geolocation) {
        try { navigator.geolocation.clearWatch(gpsTrackWatchId); } catch (e) {}
      }
      gpsTrackWatchId = null;

      var pts = gpsTrackPoints.slice();
      gpsTrackPoints = [];
      updateTrackButtonUi();
      try {
        if (typeof clearMapPopupStackingState === 'function') clearMapPopupStackingState();
        if (typeof ensureMapBottomBarVisible === 'function') ensureMapBottomBarVisible();
      } catch (eStopTrackChrome) {}

      if (opts.discard || pts.length < 2) {
        clearMapDrawPreview();
        if (!opts.discard) {
          showAppCopyToast('<span class="act">Track too short</span><br>Need at least two GPS points to save a path.');
        }
        gpsTrackStartedAt = null;
        return;
      }

      var dist = pathDistanceMiles(pts);
      var endedAt = Date.now();
      var durationMs = gpsTrackStartedAt ? (endedAt - gpsTrackStartedAt) : 0;
      var hrs = durationMs / 3600000;
      var avg = hrs > 0.00005 ? (dist / hrs) : 0;
      var elevDeltaFt = gpsTrackElevDeltaFt(pts);
      var when = new Date();
      var defaultName = 'Track ' + when.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) +
        ' ' + when.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });

      gpsTrackPending = {
        points: pts,
        distanceMi: dist,
        durationMs: durationMs,
        avgSpeedMph: avg,
        elevDeltaFt: elevDeltaFt,
        color: gpsTrackPreviewColor || '#d94136',
        defaultName: defaultName,
        notes: opts.reason === 'speed' ? 'Auto-stopped: speed exceeded 30 mph.' : ''
      };
      gpsTrackStartedAt = null;
      refreshGpsTrackPreview();
      openTrackFinishModal();
    }

    function toggleGpsTrack() {
      if (mapRadarActive) stopMapRadar();
      if (gpsTrackActive) stopGpsTrack();
      else startGpsTrack();
    }
    window.toggleGpsTrack = toggleGpsTrack;
    window.startGpsTrack = startGpsTrack;
    window.stopGpsTrack = stopGpsTrack;

    /**
     * Fetch elevations (meters) along path points via Open-Meteo, compute gain/loss/net in feet.
     */
    function fetchPathElevation(points) {
      if (!points || points.length < 2) {
        return Promise.resolve(null);
      }
      // Cap samples to keep URL reasonable (sample evenly if many vertices)
      var idxs = [];
      var sample = points;
      if (points.length > 40) {
        sample = [];
        var step = (points.length - 1) / 39;
        for (var i = 0; i < 40; i++) {
          var ix = Math.round(i * step);
          idxs.push(ix);
          sample.push(points[ix]);
        }
      } else {
        for (var j = 0; j < points.length; j++) idxs.push(j);
      }
      var lats = sample.map(function(p) { return p.lat; }).join(',');
      var lngs = sample.map(function(p) { return p.lng; }).join(',');
      var url = 'https://api.open-meteo.com/v1/elevation?latitude=' + encodeURIComponent(lats) +
        '&longitude=' + encodeURIComponent(lngs);
      return fetch(url).then(function(res) {
        if (!res.ok) throw new Error('elevation ' + res.status);
        return res.json();
      }).then(function(data) {
        var elevM = data && data.elevation;
        if (!elevM || !elevM.length) throw new Error('no elevation');
        // Stamp elevM (meters) onto path points so probes can show elev Î” at a click
        for (var s = 0; s < elevM.length && s < idxs.length; s++) {
          if (elevM[s] != null && !isNaN(elevM[s]) && points[idxs[s]]) {
            points[idxs[s]].elevM = elevM[s];
          }
        }
        // Linear fill gaps between sampled vertices
        if (points.length > elevM.length) {
          var lastKnown = null;
          var lastIdx = -1;
          for (var pi = 0; pi < points.length; pi++) {
            if (points[pi].elevM != null) {
              if (lastKnown != null && lastIdx >= 0 && pi - lastIdx > 1) {
                var span = pi - lastIdx;
                for (var k = 1; k < span; k++) {
                  var t = k / span;
                  points[lastIdx + k].elevM = lastKnown + (points[pi].elevM - lastKnown) * t;
                }
              }
              lastKnown = points[pi].elevM;
              lastIdx = pi;
            }
          }
        }
        var elevFt = elevM.map(function(m) { return m == null ? null : m * 3.28084; });
        var gain = 0, loss = 0;
        for (var ii = 1; ii < elevFt.length; ii++) {
          if (elevFt[ii] == null || elevFt[ii - 1] == null) continue;
          var d = elevFt[ii] - elevFt[ii - 1];
          if (d > 0) gain += d;
          else loss += -d;
        }
        var startFt = elevFt[0];
        var endFt = elevFt[elevFt.length - 1];
        var netFt = (startFt != null && endFt != null) ? (endFt - startFt) : null;
        return {
          startFt: startFt,
          endFt: endFt,
          netFt: netFt,
          gainFt: gain,
          lossFt: loss,
          samples: elevFt.length
        };
      });
    }

    function saveMeasuredPath(points, distanceMi, opts) {
      opts = opts || {};
      if (!points || points.length < 2) return null;
      var isTrack = opts.kind === 'track';
      var path = {
        id: (isTrack ? 'track_' : 'meas_') + Date.now(),
        kind: isTrack ? 'track' : (opts.kind || 'measure'),
        name: opts.name || (isTrack ? 'GPS track' : 'Measured line'),
        color: opts.color || (isTrack ? '#d94136' : '#38bdf8'),
        notes: opts.notes || '',
        points: points.map(function(p) {
          return { lat: p.lat, lng: p.lng, t: p.t != null ? p.t : undefined };
        }),
        distanceMi: distanceMi != null ? distanceMi : pathDistanceMiles(points),
        distanceMiAuto: distanceMi != null ? distanceMi : pathDistanceMiles(points),
        durationMs: opts.durationMs != null ? opts.durationMs : null,
        avgSpeedMph: opts.avgSpeedMph != null ? opts.avgSpeedMph : null,
        weight: opts.weight != null ? opts.weight : (isTrack ? 5 : 4),
        createdAt: new Date().toISOString(),
        elev: null,
        elevError: false
      };
      // Duration from point timestamps if not provided
      if (path.durationMs == null && path.points[0].t != null && path.points[path.points.length - 1].t != null) {
        path.durationMs = Math.max(0, path.points[path.points.length - 1].t - path.points[0].t);
      }
      if (path.avgSpeedMph == null && path.durationMs > 0) {
        var hrs = path.durationMs / 3600000;
        if (hrs > 0.00005) path.avgSpeedMph = path.distanceMi / hrs;
      }
      var paths = loadMeasuredPathsFromStorage();
      paths.push(path);
      if (paths.length > 80) paths = paths.slice(paths.length - 80);
      saveMeasuredPathsToStorage(paths);
      drawMeasuredPathsOnMap();
      fetchPathElevation(path.points).then(function(elev) {
        if (!elev) path.elevError = true;
        else path.elev = elev;
        var all = loadMeasuredPathsFromStorage();
        for (var i = 0; i < all.length; i++) {
          if (String(all[i].id) === String(path.id)) {
            all[i].elev = path.elev;
            all[i].elevError = path.elevError;
            // Persist per-point elevM for probe / tooltip at-a-point
            all[i].points = path.points;
            break;
          }
        }
        saveMeasuredPathsToStorage(all);
        drawMeasuredPathsOnMap();
      }).catch(function() {
        path.elevError = true;
        var all2 = loadMeasuredPathsFromStorage();
        for (var j = 0; j < all2.length; j++) {
          if (String(all2[j].id) === String(path.id)) {
            all2[j].elevError = true;
            break;
          }
        }
        saveMeasuredPathsToStorage(all2);
        drawMeasuredPathsOnMap();
      });
      return path;
    }

    var pathProbeState = null; // { pathId, marker, label, frac }
    function clearPathProbe() {
      if (!pathProbeState) return;
      try {
        if (pathProbeState.marker && measuredPathGroup) measuredPathGroup.removeLayer(pathProbeState.marker);
        if (pathProbeState.label && measuredPathGroup) measuredPathGroup.removeLayer(pathProbeState.label);
      } catch (eC) {}
      pathProbeState = null;
      // If path probe drag left map.dragging disabled, restore clicks/pan
      if (window._pathProbeDragging || (map && map.dragging && !map.dragging.enabled() && !window._cmDragging)) {
        try {
          if (typeof restoreMapPointerInteractions === 'function') {
            restoreMapPointerInteractions({ skipCmRefresh: true });
          } else {
            window._pathProbeDragging = false;
            try { map.dragging.enable(); } catch (eEn) {}
          }
        } catch (eR) {}
      }
    }
    function placePathProbe(path, latlng) {
      if (!map || !measuredPathGroup || !path || !path.points) return;
      clearPathProbe();
      var along = nearestAlongTimedPath(path.points, latlng);
      if (!along || along.lat == null) return;
      var color = path.color || '#d94136';
      var marker = L.circleMarker([along.lat, along.lng], {
        radius: 7,
        color: '#fff',
        weight: 2,
        fillColor: color,
        fillOpacity: 1,
        interactive: true,
        draggable: false
      });
      var distMi = along.distFromStartMi != null ? along.distFromStartMi : 0;
      var timeMs = along.elapsedMs != null ? along.elapsedMs : null;
      var elevTxt = 'â€”';
      try {
        if (along.elevM != null && path.points[0] && path.points[0].elevM != null) {
          elevTxt = formatElevDeltaFt((along.elevM - path.points[0].elevM) * 3.28084);
        } else if (path.elev && path.elev.netFt != null && path.distanceMi) {
          elevTxt = formatElevDeltaFt((along.distFromStartMi / Math.max(path.distanceMi, 1e-6)) * path.elev.netFt);
        } else if (!path.elevError && !path.elev) {
          elevTxt = 'loadingâ€¦';
        }
      } catch (eE) {}
      var html = '<div class="path-probe-popup">' +
        formatMiles(distMi) + ' from start' +
        (timeMs != null ? '<br>' + formatDurationMs(timeMs) : '') +
        '<br>Elev Î” from start: ' + elevTxt +
        '</div>';
      var label = L.marker([along.lat, along.lng], {
        interactive: false,
        icon: L.divIcon({
          className: '',
          html: html,
          iconSize: [160, 58],
          iconAnchor: [80, 66]
        })
      });
      measuredPathGroup.addLayer(marker);
      measuredPathGroup.addLayer(label);
      pathProbeState = { pathId: path.id, marker: marker, label: label, path: path, along: along };
      // Drag probe along line (document-level end so release outside map still re-enables pan)
      marker.on('mousedown', function(e) {
        window._pathProbeDragging = true;
        L.DomEvent.stop(e);
        try { map.dragging.disable(); } catch (eD) {}
      });
      marker.on('pointerdown', function(e) {
        window._pathProbeDragging = true;
        L.DomEvent.stop(e);
        try { map.dragging.disable(); } catch (eD) {}
      });
      function onMove(e) {
        if (!window._pathProbeDragging || !e.latlng) return;
        var a2 = nearestAlongTimedPath(path.points, e.latlng);
        if (!a2 || a2.lat == null) return;
        marker.setLatLng([a2.lat, a2.lng]);
        var elev2 = 'â€”';
        try {
          if (a2.elevM != null && path.points[0] && path.points[0].elevM != null) {
            elev2 = formatElevDeltaFt((a2.elevM - path.points[0].elevM) * 3.28084);
          }
        } catch (e2) {}
        var h2 = '<div class="path-probe-popup">' +
          formatMiles(a2.distFromStartMi || 0) + ' from start' +
          (a2.elapsedMs != null ? '<br>' + formatDurationMs(a2.elapsedMs) : '') +
          '<br>Elev Î” ' + elev2 + '</div>';
        label.setLatLng([a2.lat, a2.lng]);
        label.setIcon(L.divIcon({ className: '', html: h2, iconSize: [140, 54], iconAnchor: [70, 62] }));
      }
      function onUp() {
        if (!window._pathProbeDragging) return;
        window._pathProbeDragging = false;
        try {
          if (typeof restoreMapPointerInteractions === 'function') {
            restoreMapPointerInteractions({ skipCmRefresh: true });
          } else {
            try { map.dragging.enable(); } catch (eEn) {}
          }
        } catch (eU) {
          try { map.dragging.enable(); } catch (eEn2) {}
        }
      }
      map.on('mousemove', onMove);
      map.on('mouseup', onUp);
      marker.on('mouseup', onUp);
      // Document capture: mouseup outside map / pointer cancel previously left drag stuck
      if (!window._pathProbeDocWired) {
        window._pathProbeDocWired = true;
        function endPathProbeDragDoc() {
          if (!window._pathProbeDragging) return;
          window._pathProbeDragging = false;
          try {
            if (typeof restoreMapPointerInteractions === 'function') {
              restoreMapPointerInteractions({ skipCmRefresh: true });
            } else if (map && map.dragging) {
              map.dragging.enable();
            }
          } catch (eDoc) {}
        }
        document.addEventListener('mouseup', endPathProbeDragDoc, true);
        document.addEventListener('pointerup', endPathProbeDragDoc, true);
        document.addEventListener('pointercancel', endPathProbeDragDoc, true);
        document.addEventListener('touchend', endPathProbeDragDoc, true);
      }
    }
    function drawMeasuredPathsOnMap() {
      if (!map || !measuredPathGroup) return;
      clearPathProbe();
      measuredPathGroup.clearLayers();
      var paths = loadMeasuredPathsFromStorage();
      paths.forEach(function(path) {
        if (!path || !path.points || path.points.length < 2) return;
        var isTrack = path.kind === 'track';
        var color = path.color || (isTrack ? '#d94136' : '#38bdf8');
        var baseW = path.weight != null ? path.weight : (isTrack ? 5 : 4);
        var latlngs = path.points.map(function(p) { return [p.lat, p.lng]; });
        var line = L.polyline(latlngs, {
          color: color,
          weight: baseW,
          opacity: 0.92,
          lineCap: 'round',
          lineJoin: 'round',
          smoothFactor: 1.25,
          interactive: true,
          bubblingMouseEvents: false
        });
        line.bindTooltip(measuredPathTooltipHtml(path), {
          sticky: true,
          opacity: 0.97,
          className: 'measured-path-tooltip',
          direction: 'top'
        });
        // Hover along line: show distance/time from start at that point
        line.on('mousemove', function(e) {
          if (!e || !e.latlng) return;
          var along = nearestAlongTimedPath(path.points, e.latlng);
          line.setTooltipContent(measuredPathTooltipHtml(path, along));
        });
        line.on('mouseover', function() {
          try { line.setStyle({ weight: baseW + 1, opacity: 1 }); } catch (e0) {}
        });
        line.on('mouseout', function() {
          try { line.setStyle({ weight: baseW, opacity: 0.92 }); } catch (e1) {}
          line.setTooltipContent(measuredPathTooltipHtml(path));
        });
        // Click line: place distance + elevation probe at that point (drag to slide)
        line.on('click', function(e) {
          L.DomEvent.stop(e);
          placePathProbe(path, e.latlng);
        });
        line.on('dblclick', function(e) {
          L.DomEvent.stop(e);
          placePathProbe(path, e.latlng);
        });

        var safeId = escJsStr(path.id);
        var popHtml =
          '<div class="map-dot-menu" onclick="event.stopPropagation();">' +
            '<div class="mdm-title">' + escHtml(path.name || (isTrack ? 'GPS track' : 'Measured line')) + '</div>' +
            '<div class="mdm-sub">' + measuredPathTooltipHtml(path) + '</div>' +
            '<div class="mdm-sub" style="margin-top:4px;">Tap the line for distance &amp; elev Î” Â· drag the probe</div>' +
            '<button type="button" class="mdm-btn pin" onclick="event.preventDefault();event.stopPropagation();window.openPathEditModal(\'' + safeId + '\');return false;">Edit name / color / thickness</button>' +
            '<button type="button" class="mdm-btn danger" onclick="event.preventDefault();event.stopPropagation();window.deleteMeasuredPath(\'' + safeId + '\', event);return false;">Delete line</button>' +
          '</div>';
        line.bindPopup(popHtml, {
          className: 'saved-item-popup map-dot-popup',
          closeButton: true,
          autoPan: false,
          maxWidth: (typeof isPhoneLayout === 'function' && isPhoneLayout()) ? 248 : 320,
          closeOnClick: false
        });
        // Right-click / long-press menu for edit/delete (left click is the probe)
        line.on('contextmenu', function(e) {
          try { L.DomEvent.stop(e); } catch (eCr) {}
          try { line.openPopup(e.latlng); } catch (eOp) {}
        });
        line.on('popupopen', function() {
          var el = line.getPopup() && line.getPopup().getElement();
          if (el) {
            L.DomEvent.disableClickPropagation(el);
            L.DomEvent.disableScrollPropagation(el);
          }
        });
        var start = path.points[0];
        var end = path.points[path.points.length - 1];
        L.circleMarker([start.lat, start.lng], {
          radius: 5, color: '#fff', weight: 2, fillColor: color, fillOpacity: 1, interactive: false
        }).addTo(measuredPathGroup);
        L.circleMarker([end.lat, end.lng], {
          radius: 5, color: '#fff', weight: 2, fillColor: color, fillOpacity: 1, interactive: false
        }).addTo(measuredPathGroup);
        measuredPathGroup.addLayer(line);
      });
      if (mapDrawMode === 'measure' || mapDrawMode === 'draw' || mapDrawMode === 'drawline') {
        applyMapDrawInteractionLock();
      }
    }

    function deleteMeasuredPath(id, ev) {
      showMapItemConfirm('Delete this line?', function() {
        var paths = loadMeasuredPathsFromStorage().filter(function(p) { return String(p.id) !== String(id); });
        saveMeasuredPathsToStorage(paths);
        if (map) map.closePopup();
        drawMeasuredPathsOnMap();
        if (pathEditId && String(pathEditId) === String(id)) cancelPathEditModal();
      }, null, ev);
    }
    window.deleteMeasuredPath = deleteMeasuredPath;

    function openPathEditModal(id) {
      var paths = loadMeasuredPathsFromStorage();
      var path = null;
      for (var i = 0; i < paths.length; i++) {
        if (String(paths[i].id) === String(id)) { path = paths[i]; break; }
      }
      if (!path) {
        alert('Line not found.');
        return;
      }
      pathEditId = path.id;
      if (map) map.closePopup();
      var title = document.getElementById('path-edit-title');
      if (title) title.textContent = path.kind === 'track' ? 'Edit GPS track' : 'Edit measured line';
      var meta = document.getElementById('path-edit-meta');
      if (meta) {
        meta.innerHTML = 'Distance auto: ' + formatMiles(path.distanceMiAuto != null ? path.distanceMiAuto : path.distanceMi) +
          (path.durationMs != null ? ' Â· Duration ' + formatDurationMs(path.durationMs) : '') +
          (path.avgSpeedMph != null ? ' Â· Avg ' + path.avgSpeedMph.toFixed(1) + ' mph' : '');
      }
      var n = document.getElementById('path-edit-name');
      var c = document.getElementById('path-edit-color');
      var d = document.getElementById('path-edit-distance');
      var notes = document.getElementById('path-edit-notes');
      var w = document.getElementById('path-edit-weight');
      var wv = document.getElementById('path-edit-weight-val');
      if (n) n.value = path.name || '';
      var pathColor = path.color || (path.kind === 'track' ? '#d94136' : '#38bdf8');
      if (c) c.value = pathColor;
      if (d) d.value = path.distanceMi != null ? String(Math.round(path.distanceMi * 1000) / 1000) : '';
      if (notes) notes.value = path.notes || '';
      var ww = path.weight != null ? path.weight : (path.kind === 'track' ? 5 : 4);
      if (w) w.value = String(ww);
      if (wv) wv.textContent = String(ww);
      if (typeof initAllColorPickers === 'function') initAllColorPickers();
      var pathCp = document.getElementById('cp-path-edit');
      if (pathCp && typeof setColorPickerValue === 'function') setColorPickerValue(pathCp, pathColor);
      showAppPromptModal('path-edit-modal');
      setTimeout(function() { if (n) n.focus(); }, 40);
    }
    window.openPathEditModal = openPathEditModal;

    function cancelPathEditModal() {
      pathEditId = null;
      hideAppPromptModal('path-edit-modal');
    }
    window.cancelPathEditModal = cancelPathEditModal;

    function confirmPathEdit() {
      if (!pathEditId) return;
      var n = document.getElementById('path-edit-name');
      var c = document.getElementById('path-edit-color');
      var d = document.getElementById('path-edit-distance');
      var notes = document.getElementById('path-edit-notes');
      var w = document.getElementById('path-edit-weight');
      var name = n ? n.value.trim() : '';
      if (!name) {
        alert('Please enter a name.');
        if (n) n.focus();
        return;
      }
      var distVal = d ? parseFloat(String(d.value).replace(/[^0-9.]/g, '')) : NaN;
      var paths = loadMeasuredPathsFromStorage();
      for (var i = 0; i < paths.length; i++) {
        if (String(paths[i].id) === String(pathEditId)) {
          paths[i].name = name;
          paths[i].color = (c && c.value) ? c.value : paths[i].color;
          paths[i].notes = notes ? notes.value.trim() : '';
          if (w) {
            var wv = parseInt(w.value, 10);
            if (!isNaN(wv)) paths[i].weight = wv;
          }
          if (!isNaN(distVal) && distVal >= 0) {
            paths[i].distanceMi = distVal;
            // Recalc avg speed if we have duration
            if (paths[i].durationMs > 0) {
              var hrs = paths[i].durationMs / 3600000;
              if (hrs > 0.00005) paths[i].avgSpeedMph = distVal / hrs;
            }
          }
          break;
        }
      }
      saveMeasuredPathsToStorage(paths);
      drawMeasuredPathsOnMap();
      cancelPathEditModal();
      showAppCopyToast('<span class="act">Line updated</span><br>' + escHtml(name));
    }
    window.confirmPathEdit = confirmPathEdit;

    function deletePathFromEdit() {
      if (!pathEditId) return;
      var id = pathEditId;
      cancelPathEditModal();
      deleteMeasuredPath(id);
    }
    window.deletePathFromEdit = deletePathFromEdit;

    function saveCustomAreasToStorage(areas) {
      try {
        localStorage.setItem(CUSTOM_AREAS_KEY, JSON.stringify(areas || []));
      } catch (e) {
        console.warn('Could not save custom areas', e);
        alert('Could not save area (storage full?).');
      }
    }

    function loadCustomAreasIntoLocations() {
      // Remove previous custom-area location entries, then re-add from storage
      for (var i = locations.length - 1; i >= 0; i--) {
        if (locations[i] && locations[i].isCustomArea) locations.splice(i, 1);
      }
      var areas = loadCustomAreasFromStorage();
      areas.forEach(function(area) {
        if (!area || !area.ring || area.ring.length < 3) return;
        var c = ringCentroid(area.ring) || { lat: area.lat, lng: area.lng };
        var land = resolveLandContextAtPoint(c.lat, c.lng);
        locations.push({
          id: area.id,
          name: area.name || 'Custom area',
          type: land.type || 'Custom Area',
          zone: land.zone || 'A',
          lat: c.lat,
          lng: c.lng,
          color: area.lineColor || '#e59a18',
          lineColor: area.lineColor || '#e59a18',
          fillColor: area.fillColor || null,
          fillEnabled: !!area.fillEnabled,
          ring: area.ring,
          isCustomArea: true,
          isPublicLand: true,
          // false / missing â†’ map only; true â†’ can appear in Available Hunts
          hasHuntPermission: area.hasHuntPermission === true,
          landSource: land.landSource || 'custom',
          unitName: land.unitName || area.name,
          notes: (area.notes ? area.notes + ' ' : '') + (land.notes || ''),
          gisAttrs: land.gisAttrs || null,
          subSections: []
        });
      });
    }

    function customAreaPerimeterMiles(ring) {
      if (!ring || ring.length < 2) return 0;
      var t = 0;
      for (var i = 1; i < ring.length; i++) {
        t += haversineMiles(ring[i - 1][0], ring[i - 1][1], ring[i][0], ring[i][1]);
      }
      return t;
    }

    function customAreaTooltipHtml(area) {
      var perim = area.perimeterMi != null ? area.perimeterMi : customAreaPerimeterMiles(area.ring);
      var elevLine = 'Elevation: loadingâ€¦';
      if (area.elev) {
        elevLine =
          'Elevation change: <strong style="color:#fff;">' + formatElevFt(area.elev.netFt) + ' net</strong>' +
          '<br><span style="color:#c5d0be;">Gain ' + formatElevFt(area.elev.gainFt).replace('+','') +
          ' Â· Loss ' + formatElevFt(-Math.abs(area.elev.lossFt || 0)).replace('+','') + '</span>';
      } else if (area.elevError) {
        elevLine = 'Elevation: unavailable';
      }
      return (
        '<div style="min-width:160px;line-height:1.4;">' +
          '<div style="font-weight:800;color:var(--accent);margin-bottom:4px;">' + escHtml(area.name || 'Custom area') + '</div>' +
          '<div>Perimeter: <strong style="color:#fff;">' + formatMiles(perim) + '</strong></div>' +
          '<div style="margin-top:3px;">' + elevLine + '</div>' +
          '<div style="margin-top:5px;font-size:11px;color:#c5d0be;">Added: ' + escHtml(formatAddedDate(area.createdAt)) + '</div>' +
        '</div>'
      );
    }

    function drawCustomAreasOnMap() {
      if (!map || !customAreaGroup) return;
      customAreaGroup.clearLayers();
      // Layers menu â€œCustomâ€ toggle (also cleared by Public lands â†’ All off)
      if (typeof publicLandTypeVisible !== 'undefined' && publicLandTypeVisible.custom === false) {
        return;
      }
      // Prefer storage records (have elev + createdAt); fall back to location entries
      var stored = {};
      loadCustomAreasFromStorage().forEach(function(a) {
        if (a && a.id) stored[String(a.id)] = a;
      });
      locations.filter(function(l) { return l && l.isCustomArea && l.ring && l.ring.length >= 3; }).forEach(function(area) {
        var meta = stored[String(area.id)] || area;
        var line = area.lineColor || area.color || meta.lineColor || '#e59a18';
        var fillOn = (area.fillEnabled != null ? area.fillEnabled : meta.fillEnabled) && (area.fillColor || meta.fillColor);
        var fillColor = area.fillColor || meta.fillColor || line;
        var poly = L.polygon(area.ring, {
          color: line,
          weight: 1.35,
          opacity: 0.95,
          fillColor: fillOn ? fillColor : line,
          fillOpacity: fillOn ? CUSTOM_AREA_FILL_OPACITY : 0.05,
          interactive: true,
          bubblingMouseEvents: false
        });
        var tipData = {
          name: area.name || meta.name,
          ring: area.ring,
          perimeterMi: meta.perimeterMi,
          elev: meta.elev,
          elevError: meta.elevError,
          createdAt: meta.createdAt || area.createdAt
        };
        // No hover tooltip on shapes â€” info is in the click menu only
        var safeId = escJsStr(area.id);
        var popupHtml =
          '<div class="map-dot-menu" onclick="event.stopPropagation();">' +
            '<div class="mdm-title">Custom area</div>' +
            '<div class="mdm-sub">' + customAreaTooltipHtml(tipData) +
              (area.unitName ? '<br><span style="color:#c5d0be;">On: ' + escHtml(area.unitName) + '</span>' : '') +
              '<br>Zone ' + escHtml(area.zone) +
            '</div>' +
            '<button type="button" class="mdm-btn weather" onclick="event.preventDefault();event.stopPropagation();window.selectLocationById(\'' + safeId + '\',{closePopup:true,showOverlay:true,skipScroll:true});return false;">Get weather</button>' +
            '<button type="button" class="mdm-btn regs" onclick="event.preventDefault();event.stopPropagation();window.openCustomAreaRegs(\'' + safeId + '\');return false;">Rules &amp; regs</button>' +
            '<button type="button" class="mdm-btn" style="background:#1a4a5c;" onclick="event.preventDefault();event.stopPropagation();window.saveOfflineMapForCustomArea(\'' + safeId + '\');return false;">Save map offline (2 mi)</button>' +
            '<button type="button" class="mdm-btn share" onclick="event.preventDefault();event.stopPropagation();window.shareCustomArea(\'' + safeId + '\');return false;">Share location</button>' +
            '<button type="button" class="mdm-btn danger" onclick="event.preventDefault();event.stopPropagation();window.deleteCustomArea(\'' + safeId + '\', event);return false;">Delete area</button>' +
          '</div>';
        poly.bindPopup(popupHtml, {
          className: 'saved-item-popup map-dot-popup',
          closeButton: true,
          autoPan: false,
          maxWidth: (typeof isPhoneLayout === 'function' && isPhoneLayout()) ? 248 : 300,
          closeOnClick: false
        });
        poly.on('popupopen', function() {
          var el = poly.getPopup() && poly.getPopup().getElement();
          if (el) {
            L.DomEvent.disableClickPropagation(el);
            L.DomEvent.disableScrollPropagation(el);
          }
        });
        // Shape click opens menu only â€” weather and rules are separate buttons
        poly.on('click', function(e) {
          if (mapDrawMode === 'measure' || mapDrawMode === 'draw' || mapDrawMode === 'drawline') {
            if (e && e.latlng) handleMapDrawToolClick(e.latlng, e);
            return;
          }
          if (standPlaceMode && e && e.latlng) {
            placeStandAt(e.latlng.lat, e.latlng.lng);
            return;
          }
          try {
            if (e && e.originalEvent) L.DomEvent.stopPropagation(e.originalEvent);
          } catch (eSp) {}
          poly.openPopup(e && e.latlng ? e.latlng : undefined);
        });
        customAreaGroup.addLayer(poly);
      });
      if (mapDrawMode === 'measure' || mapDrawMode === 'draw' || mapDrawMode === 'drawline') {
        applyMapDrawInteractionLock();
      }
    }

    function confirmSaveCustomShape() {
      if (!pendingShapeRing || pendingShapeRing.length < 4) {
        alert('Shape is incomplete. Draw at least 3 corners, then Finish.');
        return;
      }
      var nameEl = document.getElementById('shape-name-input');
      var name = nameEl ? nameEl.value.trim() : '';
      var permChk = document.getElementById('shape-permission-chk');
      var hasHuntPermission = !!(permChk && permChk.checked);
      var lineColor = (document.getElementById('shape-line-color') || {}).value || '#e59a18';
      var fillEnabled = !!(document.getElementById('shape-fill-enabled') || {}).checked;
      var fillColor = (document.getElementById('shape-fill-color') || {}).value || lineColor;
      var c = ringCentroid(pendingShapeRing);
      if (!c) {
        alert('Could not compute area center.');
        return;
      }
      var land = resolveLandContextAtPoint(c.lat, c.lng);
      // Name optional â€” default from land under the shape, else generic
      if (!name) {
        if (land && land.unitName) name = land.unitName + ' area';
        else if (land && land.label) name = land.label + ' area';
        else name = 'Custom area';
      }
      var ringCopy = pendingShapeRing.slice();
      var perimeterMi = customAreaPerimeterMiles(ringCopy);
      var area = {
        id: 'custom_' + Date.now(),
        name: name,
        lat: c.lat,
        lng: c.lng,
        ring: ringCopy,
        lineColor: lineColor,
        fillColor: fillEnabled ? fillColor : null,
        fillEnabled: fillEnabled,
        hasHuntPermission: hasHuntPermission,
        zone: land.zone || 'A',
        landSource: land.landSource || 'custom',
        unitName: land.unitName || null,
        notes: land.notes || '',
        createdAt: new Date().toISOString(),
        perimeterMi: perimeterMi,
        elev: null,
        elevError: false
      };
      var areas = loadCustomAreasFromStorage();
      areas.push(area);
      saveCustomAreasToStorage(areas);
      loadCustomAreasIntoLocations();
      drawCustomAreasOnMap();
      // Elevation along boundary (async) for hover stats
      var elevPts = ringCopy.map(function(pt) { return { lat: pt[0], lng: pt[1] }; });
      fetchPathElevation(elevPts).then(function(elev) {
        var all = loadCustomAreasFromStorage();
        for (var i = 0; i < all.length; i++) {
          if (String(all[i].id) === String(area.id)) {
            if (elev) all[i].elev = elev;
            else all[i].elevError = true;
            break;
          }
        }
        saveCustomAreasToStorage(all);
        drawCustomAreasOnMap();
      }).catch(function() {
        var all2 = loadCustomAreasFromStorage();
        for (var j = 0; j < all2.length; j++) {
          if (String(all2[j].id) === String(area.id)) {
            all2[j].elevError = true;
            break;
          }
        }
        saveCustomAreasToStorage(all2);
        drawCustomAreasOnMap();
      });
      if (typeof updateAvailableList === 'function' && selectedDate && selectedWeapon) {
        updateAvailableList();
      }
      pendingShapeRing = null;
      cancelMapDraw();
      hideAppPromptModal('shape-save-modal');
      var listNote = hasHuntPermission
        ? 'Included in Available Hunts when open for date/weapon.'
        : 'Saved on the map only (not listed in Available Hunts â€” permission unchecked).';
      showAppCopyToast(
        '<span class="act">Area saved: ' + escHtml(name) + '</span><br>' +
        escHtml(listNote) + '<br>Rules follow ' + escHtml(land.label || ('Zone ' + area.zone)) + '.'
      );
      // Select only if it will appear in huntable list
      if (hasHuntPermission) {
        try {
          if (typeof selectLocationById === 'function') {
            selectLocationById(area.id, { closePopup: true, showOverlay: false, skipScroll: true });
          }
        } catch (selErr) {}
      }
      // Do not auto-download offline map tiles after drawing a shape.
      // Users can cache tiles separately via Offline map on the map menu.
    }
    window.confirmSaveCustomShape = confirmSaveCustomShape;

    /** Rules & regs for a saved custom shape (separate from weather) */
    function openCustomAreaRegs(id) {
      var loc = locations.find(function(l) { return l && String(l.id) === String(id); });
      if (!loc) {
        // Fall back to storage if locations not rebuilt yet
        var areas = typeof loadCustomAreasFromStorage === 'function' ? loadCustomAreasFromStorage() : [];
        var area = areas.find(function(a) { return a && String(a.id) === String(id); });
        if (!area) return;
        if (map) map.closePopup();
        openDeerRegsPanel(area.name || 'Custom area', area.landSource || 'custom', area.gisAttrs || {});
        return;
      }
      if (map) map.closePopup();
      openDeerRegsPanel(loc.name || 'Custom area', loc.landSource || 'custom', loc.gisAttrs || {});
    }
    window.openCustomAreaRegs = openCustomAreaRegs;

    function deleteCustomArea(id, ev) {
      showMapItemConfirm('Delete this custom hunt area?', function() {
        var areas = loadCustomAreasFromStorage().filter(function(a) { return String(a.id) !== String(id); });
        saveCustomAreasToStorage(areas);
        for (var i = locations.length - 1; i >= 0; i--) {
          if (locations[i] && String(locations[i].id) === String(id)) locations.splice(i, 1);
        }
        if (String(selectedLocationId) === String(id)) {
          selectedLocationId = null;
          if (typeof refreshDefaultLocationWeather === 'function') {
            refreshDefaultLocationWeather({ skipScroll: true });
          } else if (typeof resetDashboard === 'function') {
            resetDashboard();
          }
        }
        if (map) map.closePopup();
        drawCustomAreasOnMap();
        if (typeof updateAvailableList === 'function' && selectedDate && selectedWeapon) updateAvailableList();
      }, null, ev);
    }
    window.deleteCustomArea = deleteCustomArea;

    /** Google Maps link for a coordinate (opens pin at lat/lng). */
    function googleMapsShareUrl(lat, lng) {
      var la = Number(lat), lo = Number(lng);
      if (isNaN(la) || isNaN(lo)) return '';
      return 'https://www.google.com/maps?q=' + la.toFixed(6) + ',' + lo.toFixed(6);
    }

    function showAppCopyToast(messageHtml) {
      var el = document.getElementById('app-copy-toast');
      /*
       * Default: host on map-wrapper (above calendar, under toolbar).
       * When Settings (or another full-screen overlay) is open, host on body with
       * high z-index â€” otherwise Share invite toast is invisible under the modal.
       */
      var settingsOpen = false;
      try {
        var sm = document.getElementById('settings-modal');
        settingsOpen = !!(sm && sm.classList.contains('active'));
      } catch (eS) {}
      var host = settingsOpen
        ? document.body
        : (document.querySelector('.map-wrapper') || document.body);
      if (!el) {
        el = document.createElement('div');
        el.id = 'app-copy-toast';
        el.className = 'app-copy-toast';
        el.setAttribute('role', 'status');
        host.appendChild(el);
      } else if (el.parentNode !== host) {
        try { host.appendChild(el); } catch (eHost) {}
      }
      if (settingsOpen) {
        el.classList.add('app-copy-toast-over-modal');
        el.style.zIndex = '2147483646';
        el.style.position = 'fixed';
        el.style.left = '50%';
        el.style.bottom = 'auto';
        el.style.top = '50%';
        el.style.transform = 'translate(-50%, -50%)';
        el.style.maxWidth = 'min(320px, calc(100vw - 32px))';
      } else {
        el.classList.remove('app-copy-toast-over-modal');
        el.style.zIndex = '';
        el.style.position = '';
        el.style.left = '';
        el.style.bottom = '';
        el.style.top = '';
        el.style.transform = '';
        el.style.maxWidth = '';
      }
      el.innerHTML = messageHtml;
      el.classList.add('show');
      clearTimeout(showAppCopyToast._t);
      showAppCopyToast._t = setTimeout(function() {
        el.classList.remove('show');
        el.classList.remove('app-copy-toast-over-modal');
      }, 3200);
    }

    function copyTextToClipboard(text) {
      if (!text) return Promise.reject(new Error('No text'));
      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        return navigator.clipboard.writeText(text);
      }
      return new Promise(function(resolve, reject) {
        try {
          var ta = document.createElement('textarea');
          ta.value = text;
          ta.setAttribute('readonly', '');
          ta.style.position = 'fixed';
          ta.style.left = '-9999px';
          ta.style.top = '0';
          document.body.appendChild(ta);
          ta.select();
          ta.setSelectionRange(0, text.length);
          var ok = document.execCommand('copy');
          document.body.removeChild(ta);
          if (ok) resolve();
          else reject(new Error('Copy command failed'));
        } catch (e) {
          reject(e);
        }
      });
    }

    /**
     * Build Google Maps link for lat/lng, copy to clipboard, show confirmation.
     * Used from free map-dots and saved pins.
     */
    function shareLocationLink(lat, lng, label) {
      var la = Number(lat), lo = Number(lng);
      if (isNaN(la) || isNaN(lo)) {
        alert('No coordinates available to share.');
        return false;
      }
      var url = googleMapsShareUrl(la, lo);
      var title = label ? String(label) : 'Hunt location';
      copyTextToClipboard(url).then(function() {
        showAppCopyToast(
          '<span class="act">Link copied!</span><br>' +
          'Google Maps pin ready to paste into a text or email.<br>' +
          '<span style="font-size:11px;color:#c5d0be;word-break:break-all;">' + escHtml(url) + '</span>'
        );
        // Brief visual feedback on the share button in an open popup
        try {
          var btns = document.querySelectorAll('.mdm-btn.share');
          for (var i = 0; i < btns.length; i++) {
            var b = btns[i];
            if (!b._origShareLabel) b._origShareLabel = b.textContent;
            b.textContent = 'Copied!';
            b.classList.add('copied');
            (function(btn) {
              setTimeout(function() {
                btn.textContent = btn._origShareLabel || 'Share location';
                btn.classList.remove('copied');
              }, 1800);
            })(b);
          }
        } catch (uiErr) {}
      }).catch(function() {
        // Fallback: show link and try prompt so user can still copy
        showAppCopyToast(
          '<span class="act">Copy this Google Maps link:</span><br>' +
          '<span style="font-size:11px;color:#c5d0be;word-break:break-all;">' + escHtml(url) + '</span>'
        );
        try { window.prompt('Copy this Google Maps link:', url); } catch (pErr) {}
      });
      return false;
    }
    window.shareLocationLink = shareLocationLink;

    function shareSavedPinLocation(id) {
      var loc = locations.find(function(l) { return String(l.id) === String(id); });
      if (!loc || loc.lat == null || loc.lng == null) {
        alert('Pin location not found.');
        return false;
      }
      return shareLocationLink(loc.lat, loc.lng, loc.name || 'Pin');
    }
    window.shareSavedPinLocation = shareSavedPinLocation;

    function togglePinHidden(id) {
      var loc = locations.find(function(l) { return String(l.id) === String(id); });
      if (!loc || !loc.isPin) return;
      loc.hidden = !loc.hidden;
      loc._tempReveal = false;
      try {
        var pins = locations.filter(function(l) { return l && l.isPin; });
        localStorage.setItem('alabama_hunt_custom_pins', JSON.stringify(pins));
      } catch (e) {}
      if (map) try { map.closePopup(); } catch (eC) {}
      drawPinsOnMap();
      try {
        if (typeof window.regSlayerMapDataChanged === 'function') window.regSlayerMapDataChanged();
      } catch (e2) {}
    }
    window.togglePinHidden = togglePinHidden;

    /** Signed-in user for pin creator stamp (id + display name). */
    function getCurrentPinOwnerMeta() {
      var user = null;
      try {
        user = window.__rsUser || null;
        if (!user && window.RegSlayerCloud && window.RegSlayerCloud.getClient) {
          /* session may only be on auth module */
        }
      } catch (eU) {}
      var prof = null;
      try {
        if (window.RegSlayerCloud && typeof window.RegSlayerCloud.getProfile === 'function') {
          prof = window.RegSlayerCloud.getProfile();
        }
      } catch (eP) {}
      var ownerId = (user && user.id) || (prof && prof.id) || null;
      var ownerName = '';
      if (prof) {
        ownerName = (prof.display_name && String(prof.display_name).trim())
          || (prof.username && String(prof.username).trim())
          || '';
      }
      if (!ownerName && user) {
        try {
          var meta = user.user_metadata || {};
          ownerName = (meta.username || meta.display_name || '').trim();
        } catch (eM) {}
      }
      if (!ownerName && ownerId) ownerName = 'Hunter';
      if (!ownerId && !ownerName) return null;
      return { ownerId: ownerId, ownerName: ownerName || 'Hunter' };
    }
    window.getCurrentPinOwnerMeta = getCurrentPinOwnerMeta;

    /** Bold who Â· date Â· time line for pin popups. */
    function buildPinCreatorMetaHtml(loc) {
      if (!loc) return '';
      var who = (loc.ownerName && String(loc.ownerName).trim()) ? String(loc.ownerName).trim() : '';
      // Fallback: if this pin has no owner but current user is signed in, show them
      // only for brand-new unsaved edge cases â€” prefer stored ownerName.
      if (!who) {
        try {
          var om = getCurrentPinOwnerMeta();
          if (om && om.ownerName && loc.ownerId && om.ownerId && String(loc.ownerId) === String(om.ownerId)) {
            who = om.ownerName;
          } else if (om && om.ownerName && !loc.ownerId) {
            who = om.ownerName;
          }
        } catch (eF) {}
      }
      var when = '';
      try {
        var ca = loc.createdAt || loc.updatedAt;
        if (ca) {
          var d = new Date(ca);
          if (!isNaN(d.getTime())) {
            var dd = String(d.getDate()).padStart(2, '0');
            var mm = String(d.getMonth() + 1).padStart(2, '0');
            var yy = String(d.getFullYear()).slice(-2);
            var tm = d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
            when = dd + '-' + mm + '-' + yy + ' Â· ' + tm;
          }
        }
      } catch (eD) {}
      if (!who && !when) return '';
      var parts = '';
      if (who) parts += '<span class="mdm-pin-meta-who">' + escHtml(who) + '</span>';
      if (who && when) parts += '<span class="mdm-pin-meta-sep">Â·</span>';
      if (when) parts += '<span class="mdm-pin-meta-when">' + escHtml(when) + '</span>';
      return '<div class="mdm-sub mdm-pin-meta">' + parts + '</div>';
    }
    window.buildPinCreatorMetaHtml = buildPinCreatorMetaHtml;

    /**
     * Toggle emphasize: pin pulses until toggled off.
     * On shared maps this is pushed immediately so every member sees the pulse
     * (cloud pull / realtime redraws pins with .pin-emphasize-pulse).
     */
    function togglePinEmphasize(id) {
      var loc = locations.find(function(l) { return String(l.id) === String(id); });
      if (!loc || !loc.isPin) return;
      loc.emphasized = !loc.emphasized;
      loc.updatedAt = new Date().toISOString();
      try {
        var pins = locations.filter(function(l) { return l && l.isPin; });
        localStorage.setItem('alabama_hunt_custom_pins', JSON.stringify(pins));
      } catch (e) {}
      // Keep the pin visible; close popup so the pulse is easy to see
      if (map) try { map.closePopup(); } catch (eC) {}
      drawPinsOnMap();
      try {
        // Immediate cloud write so party members pick up emphasize ASAP
        if (window.RegSlayerCloud && typeof window.RegSlayerCloud.forcePush === 'function') {
          window.RegSlayerCloud.forcePush();
        } else if (typeof window.regSlayerMapDataChanged === 'function') {
          window.regSlayerMapDataChanged();
        } else if (window.RegSlayerCloud && typeof window.RegSlayerCloud.markDirty === 'function') {
          window.RegSlayerCloud.markDirty();
        }
      } catch (e2) {}
      try {
        if (typeof showAppCopyToast === 'function') {
          showAppCopyToast(loc.emphasized
            ? '<span class="act">Pin highlighted</span><br>Pulsing for everyone on this map until you turn it off'
            : '<span class="act">Highlight off</span><br>Pin pulse stopped');
        }
      } catch (eT) {}
    }
    window.togglePinEmphasize = togglePinEmphasize;
    // ---- Share flow inside the open Leaflet map popup (same window, no separate modal) ----
    var shareInPopupCtx = null;
    var shareInPopupTargets = [];

    function escShareHtml(s) {
      return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function buildShareChooserPopupHtml(label, opts) {
      opts = opts || {};
      var statusBlock = opts.statusBlock || '';
      return (
        '<div class="map-dot-menu" onclick="event.stopPropagation();">' +
          statusBlock +
          '<div class="mdm-title">Share location</div>' +
          (label ? '<div class="mdm-sub">' + escShareHtml(label) + '</div>' : '') +
          '<button type="button" class="mdm-btn pin" onclick="event.preventDefault();event.stopPropagation();window.sharePopupGoSelectMap();return false;">Share to another map</button>' +
          '<button type="button" class="mdm-btn share" onclick="event.preventDefault();event.stopPropagation();window.sharePopupCopyLocation();return false;">Copy location</button>' +
          '<button type="button" class="mdm-btn" style="background:#3a4234;" onclick="event.preventDefault();event.stopPropagation();window.sharePopupBack();return false;">Back</button>' +
        '</div>'
      );
    }

    function buildSelectMapPopupHtml(targets, opts) {
      opts = opts || {};
      var statusBlock = opts.statusBlock || '';
      var body = '';
      if (opts.loading) {
        body = '<div class="mdm-sub" style="text-align:center;padding:8px 0;">Loading mapsâ€¦</div>';
      } else if (opts.error) {
        body = '<div class="mdm-sub" style="text-align:center;padding:8px 0;">Could not load maps.</div>';
      } else if (opts.empty || !targets || !targets.length) {
        body = '<div class="mdm-sub" style="text-align:center;padding:8px 0;">No other maps yet.</div>';
      } else {
        body = targets.map(function(t, i) {
          return '<button type="button" class="mdm-btn pin" style="width:100%;margin-bottom:6px;" ' +
            'onclick="event.preventDefault();event.stopPropagation();window.sharePopupPickMap(' + i + ');return false;">' +
            escShareHtml(t.name || 'Map') + '</button>';
        }).join('');
      }
      return (
        '<div class="map-dot-menu" onclick="event.stopPropagation();">' +
          statusBlock +
          '<div class="mdm-title">Select Map</div>' +
          body +
          '<button type="button" class="mdm-btn" style="background:#3a4234;width:100%;margin-top:4px;" ' +
            'onclick="event.preventDefault();event.stopPropagation();window.sharePopupShowChooser();return false;">Back</button>' +
        '</div>'
      );
    }

    function findOpenSharePopupLayer() {
      if (!map) return null;
      if (mapDotMenuSource === 'gps' && gpsMarker && gpsMarker.isPopupOpen && gpsMarker.isPopupOpen()) {
        return gpsMarker;
      }
      if (tempClickMarker && tempClickMarker.isPopupOpen && tempClickMarker.isPopupOpen()) {
        return tempClickMarker;
      }
      var found = null;
      try {
        map.eachLayer(function(layer) {
          if (found) return;
          try {
            if (layer && typeof layer.isPopupOpen === 'function' && layer.isPopupOpen() &&
                typeof layer.setPopupContent === 'function') {
              found = layer;
            }
          } catch (eL) {}
        });
      } catch (e) {}
      return found;
    }

    function setOpenMapPopupHtml(html) {
      var layer = findOpenSharePopupLayer();
      if (layer) {
        try { layer.setPopupContent(html); return true; } catch (eS) {}
      }
      // Fallback: open a popup at share coords so UI still appears on-map
      if (map && shareInPopupCtx && shareInPopupCtx.lat != null && shareInPopupCtx.lng != null) {
        try {
          L.popup({ className: 'saved-item-popup map-dot-popup', maxWidth: 280, autoPan: false, closeOnClick: false })
            .setLatLng([shareInPopupCtx.lat, shareInPopupCtx.lng])
            .setContent(html)
            .openOn(map);
          return true;
        } catch (eP) {}
      }
      return false;
    }

    function beginShareInMapPopup(ctx) {
      shareInPopupCtx = ctx || {};
      shareInPopupTargets = [];
      var html = buildShareChooserPopupHtml(shareInPopupCtx.label || 'Location', {
        fromGps: shareInPopupCtx.host === 'gps' || mapDotMenuSource === 'gps'
      });
      // Prefer existing open popup content swap
      if (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps') {
        setMapDotMenuContent({
          shareChooser: true,
          fromGps: shareInPopupCtx.host === 'gps' || mapDotMenuSource === 'gps',
          shareName: shareInPopupCtx.label
        });
        return true;
      }
      return setOpenMapPopupHtml(html);
    }

    function sharePopupShowChooser() {
      if (!shareInPopupCtx) return false;
      if (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps') {
        setMapDotMenuContent({
          shareChooser: true,
          fromGps: shareInPopupCtx.host === 'gps' || mapDotMenuSource === 'gps',
          shareName: shareInPopupCtx.label
        });
        return false;
      }
      setOpenMapPopupHtml(buildShareChooserPopupHtml(shareInPopupCtx.label || 'Location', {}));
      return false;
    }

    function sharePopupCopyLocation() {
      if (!shareInPopupCtx) return false;
      shareLocationLink(shareInPopupCtx.lat, shareInPopupCtx.lng, shareInPopupCtx.label || 'Location');
      // Stay on same share options after copy
      sharePopupShowChooser();
      return false;
    }

    function sharePopupBack() {
      if (shareInPopupCtx && (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps')) {
        setMapDotMenuContent({ fromGps: shareInPopupCtx.host === 'gps' || mapDotMenuSource === 'gps' });
        return false;
      }
      // Pin / shape: re-open original menu by closing is fine; try main pin rebuild via re-click is heavy
      try { if (map) map.closePopup(); } catch (e) {}
      shareInPopupCtx = null;
      return false;
    }

    function showSelectMapInMapPopup() {
      if (!shareInPopupCtx) {
        // Seed from map-dot context
        shareInPopupCtx = {
          lat: clickLat,
          lng: clickLng,
          label: mapDotMenuSource === 'gps' ? 'My location' : 'Map spot',
          entity: { lat: clickLat, lng: clickLng, name: mapDotMenuSource === 'gps' ? 'My location' : 'Map spot' },
          defaultType: 'pin',
          host: mapDotMenuSource === 'gps' ? 'gps' : 'dot'
        };
      }
      var loadingHtml = buildSelectMapPopupHtml([], { loading: true });
      if (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps') {
        setMapDotMenuContent({
          selectMap: true,
          mapLoading: true,
          fromGps: shareInPopupCtx.host === 'gps'
        });
      } else {
        setOpenMapPopupHtml(loadingHtml);
      }

      var RP = window.RegSlayerParty;
      if (!RP || typeof RP.listAllTargetMaps !== 'function') {
        var errHtml = buildSelectMapPopupHtml([], { error: true });
        if (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps') {
          setMapDotMenuContent({ selectMap: true, mapError: true, fromGps: shareInPopupCtx.host === 'gps' });
        } else setOpenMapPopupHtml(errHtml);
        return false;
      }
      Promise.resolve(RP.listAllTargetMaps()).then(function(targets) {
        shareInPopupTargets = targets || [];
        if (!shareInPopupTargets.length) {
          if (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps') {
            setMapDotMenuContent({ selectMap: true, mapEmpty: true, fromGps: shareInPopupCtx.host === 'gps' });
          } else {
            setOpenMapPopupHtml(buildSelectMapPopupHtml([], { empty: true }));
          }
          return;
        }
        if (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps') {
          setMapDotMenuContent({
            selectMap: true,
            mapTargets: shareInPopupTargets,
            fromGps: shareInPopupCtx.host === 'gps'
          });
        } else {
          setOpenMapPopupHtml(buildSelectMapPopupHtml(shareInPopupTargets, {}));
        }
      }).catch(function() {
        if (shareInPopupCtx.host === 'dot' || shareInPopupCtx.host === 'gps') {
          setMapDotMenuContent({ selectMap: true, mapError: true, fromGps: shareInPopupCtx.host === 'gps' });
        } else {
          setOpenMapPopupHtml(buildSelectMapPopupHtml([], { error: true }));
        }
      });
      return false;
    }

    function sharePopupGoSelectMap() {
      return showSelectMapInMapPopup();
    }

    function sharePopupPickMap(idx) {
      var t = shareInPopupTargets[idx];
      if (!t || !shareInPopupCtx) return false;
      var RP = window.RegSlayerParty;
      if (!RP || typeof RP.copyEntityToMap !== 'function') {
        alert('Sign in to share to another map.');
        return false;
      }
      var ent = shareInPopupCtx.entity || {
        lat: shareInPopupCtx.lat,
        lng: shareInPopupCtx.lng,
        name: shareInPopupCtx.label
      };
      var typ = shareInPopupCtx.defaultType || 'pin';
      // Show sharing state in same popup
      setOpenMapPopupHtml(
        '<div class="map-dot-menu"><div class="mdm-title">Select Map</div>' +
        '<div class="mdm-sub" style="text-align:center;padding:10px 0;">Sharing to ' +
        escShareHtml(t.name) + 'â€¦</div></div>'
      );
      Promise.resolve(RP.copyEntityToMap(ent, typ, t)).then(function() {
        try { if (map) map.closePopup(); } catch (e) {}
        shareInPopupCtx = null;
        shareInPopupTargets = [];
        if (typeof showAppCopyToast === 'function') {
          showAppCopyToast('<span class="act">Shared to map</span><br>' + escShareHtml(t.name));
        }
      }).catch(function(e) {
        alert((e && e.message) || String(e));
        sharePopupShowChooser();
      });
      return false;
    }

    window.sharePopupShowChooser = sharePopupShowChooser;
    window.sharePopupCopyLocation = sharePopupCopyLocation;
    window.sharePopupBack = sharePopupBack;
    window.sharePopupGoSelectMap = sharePopupGoSelectMap;
    window.sharePopupPickMap = sharePopupPickMap;
    window.beginShareInMapPopup = beginShareInMapPopup;
    window.showSelectMapInMapPopup = showSelectMapInMapPopup;
    window.setOpenMapPopupHtml = setOpenMapPopupHtml;
    window.buildShareChooserPopupHtml = buildShareChooserPopupHtml;
    window.buildSelectMapPopupHtml = buildSelectMapPopupHtml;

    function sharePinToAnotherMap(id) {
      var loc = locations.find(function(l) { return String(l.id) === String(id); });
      if (!loc) {
        try {
          var pins = JSON.parse(localStorage.getItem('alabama_hunt_custom_pins') || '[]');
          if (Array.isArray(pins)) {
            loc = pins.find(function(p) { return p && String(p.id) === String(id); }) || null;
          }
        } catch (eP) {}
      }
      if (!loc) { alert('Pin not found.'); return false; }
      beginShareInMapPopup({
        lat: loc.lat,
        lng: loc.lng,
        label: loc.name || 'Pin',
        entity: loc,
        defaultType: 'pin',
        host: 'pin'
      });
      showSelectMapInMapPopup();
      return false;
    }
    window.sharePinToAnotherMap = sharePinToAnotherMap;

    function shareSavedPinChooser(id) {
      var loc = locations.find(function(l) { return String(l.id) === String(id); });
      if (!loc) return false;
      // Same pin popup â†’ share options (do not open a separate window)
      beginShareInMapPopup({
        lat: loc.lat,
        lng: loc.lng,
        label: loc.name || 'Pin',
        entity: loc,
        defaultType: 'pin',
        host: 'pin'
      });
      setOpenMapPopupHtml(buildShareChooserPopupHtml(loc.name || 'Pin', {}));
      return false;
    }
    window.shareSavedPinChooser = shareSavedPinChooser;

    /** Shape / custom area share â€” same in-popup flow */
