    /* --- PlanSlayer event list viewer (slayer_event_lists_v1) --- */
    var _svlPack = null;
    var _svlTab = null;
    var _svlMinimized = {};
    function loadSlayerEventListBag() {
      try {
        var bag = JSON.parse(localStorage.getItem('slayer_event_lists_v1') || '{}') || {};
        return bag && typeof bag === 'object' ? bag : {};
      } catch (e) { return {}; }
    }
    function findSlayerEventListPack(ev) {
      if (!ev) return null;
      // Embedded on calendar event (local dual-write or cloud hunt_link)
      if (ev.listPack && (ev.listPack.columns || ev.listPack.name)) return ev.listPack;
      var bag = loadSlayerEventListBag();
      if (ev.planListId && bag['list:' + ev.planListId]) return bag['list:' + ev.planListId];
      if (bag['hunt:' + ev.id]) return bag['hunt:' + ev.id];
      if (bag[String(ev.id)]) return bag[String(ev.id)];
      if (ev.planEventId && bag[String(ev.planEventId)]) return bag[String(ev.planEventId)];
      // name match last resort
      var name = String(ev.text || ev.name || '').toLowerCase();
      if (name) {
        var keys = Object.keys(bag);
        for (var i = 0; i < keys.length; i++) {
          var p = bag[keys[i]];
          if (p && p.eventName && String(p.eventName).toLowerCase() === name) return p;
          if (p && p.name && String(p.name).toLowerCase().indexOf(name) >= 0) return p;
        }
      }
      return null;
    }
    function openSlayerViewList(ev) {
      if (window.PlanEventsListsKit && typeof window.PlanEventsListsKit.openListFloat === 'function' && ev) {
        try { window.PlanEventsListsKit.openListFloat({ event: ev }); return; } catch (eFl) {}
      }
      var pack = findSlayerEventListPack(ev);
      if (!pack) {
        if (typeof showAppCopyToast === 'function') {
          showAppCopyToast('<span class="act">No list yet</span><br>Open this event in PlanSlayer and add items first.');
        } else {
          try { alert('No packing list found. Create/open the event in PlanSlayer first.'); } catch (e) {}
        }
        return;
      }
      _svlPack = pack;
      _svlTab = (pack.columns && pack.columns[0] && pack.columns[0].id) || 'todo';
      _svlMinimized = {};
      renderSlayerViewList();
      var sheet = document.getElementById('slayer-view-list-sheet');
      if (sheet) {
        sheet.classList.add('is-open');
        sheet.setAttribute('aria-hidden', 'false');
      }
    }
    function closeSlayerViewList() {
      var sheet = document.getElementById('slayer-view-list-sheet');
      if (sheet) {
        sheet.classList.remove('is-open');
        sheet.setAttribute('aria-hidden', 'true');
      }
      _svlPack = null;
      _svlMinimized = {};
    }
    function renderSlayerViewList() {
      if (!_svlPack) return;
      var title = document.getElementById('svl-title');
      var tabs = document.getElementById('svl-tabs');
      var body = document.getElementById('svl-body');
      if (title) title.textContent = (_svlPack.eventName || _svlPack.name || 'List') + ' Â· list';
      var cols = _svlPack.columns || [];
      if (tabs) {
        tabs.innerHTML = cols.map(function (c) {
          var on = String(c.id) === String(_svlTab);
          var n = (c.items && c.items.length) ? (' Â· ' + c.items.length) : '';
          return '<button type="button" class="svl-tab' + (on ? ' is-active' : '') +
            '" data-svl-tab="' + String(c.id).replace(/"/g, '') + '">' +
            String(c.name || c.id).replace(/</g, '&lt;') + n + '</button>';
        }).join('') || '';
      }
      var col = cols.find(function (c) { return String(c.id) === String(_svlTab); }) || cols[0];
      if (body) {
        if (!col) {
          body.innerHTML = '<p class="svl-empty">Nothing in this section yet.</p>';
          return;
        }
        var cid = String(col.id || 'todo');
        var mini = !!_svlMinimized[cid];
        var head =
          '<div class="svl-col' + (mini ? ' is-minimized' : '') + '" data-svl-col="' + cid.replace(/"/g, '') + '">' +
          '<div class="svl-col-head">' +
          '<div class="svl-col-title">' + String(col.name || col.id || 'Section').replace(/</g, '&lt;') + '</div>' +
          '<div class="svl-col-actions">' +
          '<button type="button" data-svl-act="settings" data-svl-col="' + cid.replace(/"/g, '') + '" title="Settings">âš™</button>' +
          '<button type="button" data-svl-act="share" data-svl-col="' + cid.replace(/"/g, '') + '" title="Share section">â¤´</button>' +
          '<button type="button" data-svl-act="minimize" data-svl-col="' + cid.replace(/"/g, '') + '" title="' +
            (mini ? 'Expand' : 'Minimize') + '">' + (mini ? '+' : 'âˆ’') + '</button>' +
          '</div></div>';
        var itemsHtml = '';
        if (!(col.items || []).length) {
          itemsHtml = '<p class="svl-empty">Nothing in this section yet.</p>';
        } else {
          itemsHtml = '<div class="svl-col-items">' + (col.items || []).map(function (it) {
            var q = (it.qty && Number(it.qty) > 1) ? ('<span class="svl-qty">Ã—' + it.qty + '</span>') : '';
            return '<div class="svl-item">' + String(it.title || 'Item').replace(/</g, '&lt;') + q + '</div>';
          }).join('') + '</div>';
        }
        body.innerHTML = head + itemsHtml + '</div>';
      }
    }
    function wireSlayerViewListUi() {
      if (document._svlWired) return;
      document._svlWired = true;
      var closeBtn = document.getElementById('svl-close');
      if (closeBtn) closeBtn.addEventListener('click', closeSlayerViewList);
      var sheet = document.getElementById('slayer-view-list-sheet');
      if (sheet) {
        sheet.addEventListener('click', function (e) {
          if (e.target === sheet) closeSlayerViewList();
        });
      }
      var tabs = document.getElementById('svl-tabs');
      if (tabs) {
        tabs.addEventListener('click', function (e) {
          var t = e.target && e.target.closest && e.target.closest('[data-svl-tab]');
          if (!t) return;
          _svlTab = t.getAttribute('data-svl-tab');
          renderSlayerViewList();
        });
      }
      var body = document.getElementById('svl-body');
      if (body) {
        body.addEventListener('click', function (e) {
          var b = e.target && e.target.closest && e.target.closest('[data-svl-act]');
          if (!b) return;
          var act = b.getAttribute('data-svl-act');
          var colId = b.getAttribute('data-svl-col') || _svlTab;
          if (act === 'minimize') {
            _svlMinimized[colId] = !_svlMinimized[colId];
            renderSlayerViewList();
            return;
          }
          if (act === 'settings') {
            if (typeof showAppCopyToast === 'function') {
              showAppCopyToast('<span class="act">List settings</span><br>Edit packing list options in PlanSlayer.');
            }
            return;
          }
          if (act === 'share') {
            try {
              var col = (_svlPack.columns || []).find(function (c) { return String(c.id) === String(colId); });
              var lines = (col && col.items || []).map(function (it) {
                return (it.title || 'Item') + (it.qty > 1 ? (' Ã—' + it.qty) : '');
              });
              var text = (col && col.name ? col.name + '\n' : '') + lines.join('\n');
              if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(function () {
                  if (typeof showAppCopyToast === 'function') showAppCopyToast('Section copied');
                }).catch(function () {
                  if (typeof showAppCopyToast === 'function') showAppCopyToast(text || 'Nothing to share');
                });
              } else if (typeof showAppCopyToast === 'function') {
                showAppCopyToast(text || 'Nothing to share');
              }
            } catch (eS) {}
          }
        });
      }
    }
    window.openSlayerViewList = openSlayerViewList;
    window.closeSlayerViewList = closeSlayerViewList;
    window.findSlayerEventListPack = findSlayerEventListPack;
    try { wireSlayerViewListUi(); } catch (eW) {}


