      if (map && typeof L !== 'undefined') {
        L.popup().setLatLng([lat, lng]).setContent('<strong>' + standName + '</strong><br>Stand saved').openOn(map);
        setTimeout(function() { if (map) map.closePopup(); }, 1600);
      }
