          var tid = detected.zone==='A' ? 10 : 11;
          var rule = rules.find(function(r) { return r.locId==tid && dateStr>=r.start && dateStr<=r.end; }) || { weapon:'General', target:'Statewide Rules', limit:'Statewide Limit', notes:'Check regulations.' };
          // Do NOT force panZoom â€” map already panned at current zoom
