    function showSettingsInfo(btn, ev) {
      if (ev) {
        try { ev.preventDefault(); ev.stopPropagation(); } catch (e0) {}
      }
      if (!btn) return false;
      var pop = document.getElementById('settings-info-pop');
      var body = document.querySelector('#settings-modal .settings-body');
      if (!pop || !body) return false;
      // Toggle off if same button
      if (btn.classList.contains('is-open') && pop.classList.contains('open')) {
        hideSettingsInfo();
        return false;
      }
      hideSettingsInfo();
      var title = btn.getAttribute('data-title') || '';
      var info = btn.getAttribute('data-info') || btn.getAttribute('title') || '';
      if (!info) return false;
      function esc(s) {
        return String(s)
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;');
      }
      pop.innerHTML = (title ? '<span class="sip-title">' + esc(title) + '</span>' : '') + esc(info);
      pop.hidden = false;
      pop.classList.add('open');
      btn.classList.add('is-open');
      // Position inside settings-body near the button
      var br = btn.getBoundingClientRect();
      var bodyR = body.getBoundingClientRect();
      var left = br.right - bodyR.left - 200;
      var top = br.bottom - bodyR.top + body.scrollTop + 6;
      left = Math.max(8, Math.min(left, bodyR.width - 200));
      pop.style.left = Math.round(left) + 'px';
      pop.style.top = Math.round(top) + 'px';
      // Keep fully on-screen after layout
      requestAnimationFrame(function() {
        var pr = pop.getBoundingClientRect();
        if (pr.right > bodyR.right - 6) {
          pop.style.left = Math.max(8, Math.round(bodyR.width - pr.width - 10)) + 'px';
        }
        if (pr.bottom > bodyR.bottom - 6) {
          var above = br.top - bodyR.top + body.scrollTop - pr.height - 6;
          pop.style.top = Math.max(body.scrollTop + 4, Math.round(above)) + 'px';
        }
      });
      return false;
    }
