      var body = document.getElementById('mwo-body');
      var title = document.getElementById('mwo-title');
      var more = document.getElementById('mwo-more-btn');
      if (!overlay || !body) return;

      var wspd, wdir, tempNow;
      var windIsCurrent = !!(weather.isCurrent && weather.current);
      if (windIsCurrent) {
        wspd = weather.current.wind_speed_10m;
        wdir = weather.current.wind_direction_10m;
        tempNow = weather.current.temperature_2m;
      } else {
        var hourly = weather.hourly || {};
        var idx = (hourly.wind_speed_10m && hourly.wind_speed_10m[7] !== undefined) ? 7 : 12;
        wspd = (hourly.wind_speed_10m && hourly.wind_speed_10m[idx]) || 5;
        wdir = (hourly.wind_direction_10m && hourly.wind_direction_10m[idx]) || 320;
        tempNow = hourly.temperature_2m && hourly.temperature_2m[idx];
      }
      var dayTemps = typeof getDayHighLow === 'function' ? getDayHighLow(weather) : { high: null, low: null };
      var sun = (lat != null && lng != null && typeof calculateAstronomicalSunriseSunset === 'function')
        ? calculateAstronomicalSunriseSunset(lat, lng, selectedDate || new Date(), typeof getAlabamaTimezoneOffset === 'function' ? getAlabamaTimezoneOffset(selectedDate || new Date()) : -6)
        : { sunrise: '--', sunset: '--' };
      var moon = typeof calculateMoonPhase === 'function' ? calculateMoonPhase(selectedDate || new Date()) : { phase: 'â€”', illumination: 'â€”' };

      var name = (location && location.name) || 'Map spot';
      if (title) title.textContent = name;
      var windCell = (typeof hourlyWindCellHtml === 'function')
        ? hourlyWindCellHtml(wspd, wdir)
        : (Math.round(wspd || 0) + ' mph ' + getCardinal(wdir || 0));
      var compact =
        '<div style="font-weight:bold;color:var(--accent);margin-bottom:6px;">' +
        formatTemp(tempNow) + ' Â· Wind ' + Math.round(wspd || 0) + ' mph ' + getCardinal(wdir || 0) +
        '</div>' +
        '<div>High ' + formatTemp(dayTemps.high) + ' Â· Low ' + formatTemp(dayTemps.low) + '</div>' +
        '<div style="margin-top:4px;color:var(--muted);font-size:11px;">Sunrise ' + (sun.sunrise || '--') +
        ' Â· Sunset ' + (sun.sunset || '--') + '</div>';

      var hourlyRows = '';
      if (weather.hourly && weather.hourly.time) {
        for (var h = 5; h <= 18; h++) {
          if (!weather.hourly.time[h]) continue;
          var t = new Date(weather.hourly.time[h]);
          var rainPct = (weather.hourly.precipitation_probability && weather.hourly.precipitation_probability[h] != null)
            ? Math.round(weather.hourly.precipitation_probability[h])
            : ((weather.hourly.precipitation_probability_mean && weather.hourly.precipitation_probability_mean[h] != null)
              ? Math.round(weather.hourly.precipitation_probability_mean[h])
              : 'â€”');
          var hWind = (typeof hourlyWindCellHtml === 'function')
            ? hourlyWindCellHtml(weather.hourly.wind_speed_10m[h], weather.hourly.wind_direction_10m && weather.hourly.wind_direction_10m[h])
            : (Math.round(weather.hourly.wind_speed_10m[h] || 0) + '');
          hourlyRows += '<tr>' +
            '<td style="border-right:1px solid rgba(255,255,255,0.12);padding:2px 3px;text-align:center;">' + t.toLocaleTimeString('en-US', { hour: 'numeric' }) + '</td>' +
            '<td style="border-right:1px solid rgba(255,255,255,0.12);padding:2px 3px;text-align:center;">' + formatTemp(weather.hourly.temperature_2m[h]) + '</td>' +
            '<td style="border-right:1px solid rgba(255,255,255,0.12);padding:2px 3px;text-align:center;">' + (rainPct === 'â€”' ? 'â€”' : rainPct + '%') + '</td>' +
            '<td class="hourly-wind-td" style="padding:2px 3px;text-align:center;">' + hWind + '</td></tr>';
        }
      }
      var thStyle = 'border-right:1px solid rgba(255,255,255,0.18);padding:2px 2px;font-size:10px;font-weight:700;text-align:center;white-space:nowrap;';
      var details =
        '<div style="margin-bottom:8px;"><strong>Wind</strong>' +
        '<div class="mwd-wind-row">' + windCell +
        '<span style="color:var(--muted);font-size:11px;">from ' + getCardinal(wdir || 0) +
        ' Â· Scent â†’ ' + getCardinal(((wdir || 0) + 180) % 360) + '</span></div></div>' +
        '<div style="margin-bottom:8px;"><strong>Sun &amp; moon</strong><br>Sunrise ' + (sun.sunrise || '--') +
        ' Â· Sunset ' + (sun.sunset || '--') + '<br>Moon: ' + (moon.phase || 'â€”') +
        (moon.illumination != null ? ' (' + moon.illumination + '% lit)' : '') + '</div>' +
        '<div style="margin-bottom:8px;"><strong>High / Low</strong><br>' +
        formatTemp(dayTemps.high) + ' / ' + formatTemp(dayTemps.low) + '</div>' +
        '<div><strong>Hourly</strong>' +
        '<table style="width:100%;table-layout:fixed;font-size:10px;margin-top:4px;border-collapse:collapse;">' +
        '<thead><tr>' +
        '<th style="' + thStyle + '">Hour</th>' +
        '<th style="' + thStyle + '">Temp</th>' +
        '<th style="' + thStyle + '">Rain %</th>' +
        '<th style="padding:2px 2px;font-size:10px;font-weight:700;text-align:center;">Wind</th>' +
        '</tr></thead><tbody>' +
        hourlyRows + '</tbody></table></div>' +
        '<p style="font-size:10px;color:var(--muted);margin-top:8px;">Confirm Outdoor Alabama regs before hunting. Weather is planning-only.</p>';

      lastMapWeatherPayload = { title: name, compactHtml: compact, detailsHtml: details };
      body.innerHTML = compact;
      if (more) more.style.display = 'block';
