      try {
        if (typeof loadWmaZoneGeometries === 'function') loadWmaZoneGeometries();
      } catch (eWzBoot) {}
      // Phone vs desktop layout (also runs early in <head>; re-apply with body ready)
      applyDeviceLayout(true);
